      active: "bg-orange-600 border-orange-700 text-white shadow-lg shadow-orange-200 ring-2 ring-orange-400 transform scale-105",
      inactive: "bg-white border-orange-100 text-orange-800 hover:bg-orange-50 hover:border-orange-300"
  },
  [ServiceCategory.ELDERLY_CARE]: {
      active: "bg-emerald-600 border-emerald-700 text-white shadow-lg shadow-emerald-200 ring-2 ring-emerald-400 transform scale-105",
      inactive: "bg-white border-emerald-100 text-emerald-800 hover:bg-emerald-50 hover:border-emerald-300"
  },
  [ServiceCategory.GARDENING]: {
      active: "bg-green-600 border-green-700 text-white shadow-lg shadow-green-200 ring-2 ring-green-400 transform scale-105",
      inactive: "bg-white border-green-100 text-green-800 hover:bg-green-50 hover:border-green-300"
  },
  [ServiceCategory.LAUNDRY]: {
      active: "bg-indigo-600 border-indigo-700 text-white shadow-lg shadow-indigo-200 ring-2 ring-indigo-400 transform scale-105",
      inactive: "bg-white border-indigo-100 text-indigo-800 hover:bg-indigo-50 hover:border-indigo-300"
  },
  [ServiceCategory.BABYSITTING]: {
      active: "bg-pink-600 border-pink-700 text-white shadow-lg shadow-pink-200 ring-2 ring-pink-400 transform scale-105",
      inactive: "bg-white border-pink-100 text-pink-800 hover:bg-pink-50 hover:border-pink-300"
  },
  [ServiceCategory.MARKET]: {
      active: "bg-amber-600 border-amber-700 text-white shadow-lg shadow-amber-200 ring-2 ring-amber-400 transform scale-105",
      inactive: "bg-white border-amber-100 text-amber-800 hover:bg-amber-50 hover:border-amber-300"
  },
};

export default function ClientDashboard({
  currentUser,
  missions,
  onAddMission,
  onValidateMission,
  onDisputeMission,
  onRateMission,
  baseRates,
  commissionRate,
  onUpdateUser
}: ClientDashboardProps) {
  const [activeTab, setActiveTab] = useState<'new' | 'history' | 'profile'>('new');

  // --- New Mission State ---
  const [selectedCategory, setSelectedCategory] = useState<ServiceCategory>(ServiceCategory.CLEANING);
  const [description, setDescription] = useState('');
  const [date, setDate] = useState('');
  const [time, setTime] = useState(''); 
  const [endTime, setEndTime] = useState(''); 
  const [duration, setDuration] = useState(2); 

  const [laundryQuantity, setLaundryQuantity] = useState<number>(20); 

  const [location, setLocation] = useState<string>(currentUser.address || '');
  const [debouncedLocation, setDebouncedLocation] = useState<string>(currentUser.address || '');
  const [city, setCity] = useState(currentUser.city || 'Abidjan');
  const [isLocating, setIsLocating] = useState(false);
  const [statusFilter, setStatusFilter] = useState<string>('TOUTES');

  // Market Specifics
  const [marketItems, setMarketItems] = useState<MarketItem[]>([]);
  const [newItemName, setNewItemName] = useState('');
  const [newItemPrice, setNewItemPrice] = useState<string>(''); 
  const [deliveryWindow, setDeliveryWindow] = useState("Aujourd'hui avant 14h");

  // Payment Modal
