    setIsLocating(true);
    navigator.geolocation.getCurrentPosition(
        async (position) => {
            const { latitude, longitude } = position.coords;
            const latLng = `${latitude.toFixed(5)}, ${longitude.toFixed(5)}`;
            setLocation(latLng);

            try {
                const response = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}`);
                const data = await response.json();
                if (data && data.address) {
                    const formattedAddr = [data.address.road, data.address.suburb].filter(Boolean).join(', ');
                    if (formattedAddr) setLocation(`${formattedAddr} (${latLng})`);
                    if (data.address.city) setCity(data.address.city);
                }
            } catch (e) {}
            setIsLocating(false);
        },
        () => setIsLocating(false),
        { enableHighAccuracy: true }
    );
  };

  const handleAddItem = () => {
      const price = parseFloat(newItemPrice);
      if (!newItemName || isNaN(price) || price <= 0) return;
