  [ServiceCategory.ELDERLY_CARE]: { active: "bg-emerald-600 border-emerald-700 text-white shadow-lg scale-105 ring-2 ring-emerald-300", inactive: "bg-white border-emerald-100 text-emerald-700 hover:bg-emerald-50" },
  [ServiceCategory.GARDENING]: { active: "bg-green-600 border-green-700 text-white shadow-lg scale-105 ring-2 ring-green-300", inactive: "bg-white border-green-100 text-green-700 hover:bg-green-50" },
  [ServiceCategory.LAUNDRY]: { active: "bg-indigo-600 border-indigo-700 text-white shadow-lg scale-105 ring-2 ring-indigo-300", inactive: "bg-white border-indigo-100 text-indigo-700 hover:bg-indigo-50" },
  [ServiceCategory.BABYSITTING]: { active: "bg-pink-600 border-pink-700 text-white shadow-lg scale-105 ring-2 ring-pink-300", inactive: "bg-white border-pink-100 text-pink-700 hover:bg-pink-50" },
  [ServiceCategory.MARKET]: { active: "bg-amber-600 border-amber-700 text-white shadow-lg scale-105 ring-2 ring-amber-300", inactive: "bg-white border-amber-100 text-amber-700 hover:bg-amber-50" },
};

export default function ClientDashboard({
