      if (selectedCategory !== ServiceCategory.MARKET && !description) { alert("Description requise."); return; }
      if (selectedCategory === ServiceCategory.MARKET && marketItems.length === 0) { alert("Ajoutez des articles."); return; }

      setShowPaymentModal(true);
  };

  const confirmPayment = async () => {
      setIsProcessingPayment(true);

      // Auto-fill dates for Market if missing
      let finalDate = date;
      let finalTime = time;
      if (selectedCategory === ServiceCategory.MARKET) {
          const now = new Date();
          if (!finalDate) finalDate = now.toISOString().split('T')[0];
          if (!finalTime) finalTime = now.toLocaleTimeString('en-US', { hour12: false, hour: "2-digit", minute: "2-digit" });
