Correction majeure du formulaire : Séparation stricte des inputs fichiers et textes pour éviter les chevauchements (bug ID Number), correction du téléchargement Verso, et amélioration de la grille des compétences pour le mobile.

```tsx
import React, { useState, useEffect, useRef } from 'react';
import { UserRole, User, ServiceCategory } from '../types';
import { Eye, EyeOff, Lock, Phone, User as UserIcon, CheckCircle, Camera, AlertCircle, Loader2, MapPin, Briefcase, LayoutGrid, ShieldCheck, ChevronDown, ChevronLeft, Smartphone } from 'lucide-react';
import { uploadImage, auth, RecaptchaVerifier, signInWithPhoneNumber } from '../services/firebase';
import { CITIES } from '../constants';

const BACKGROUND_IMAGE = "https://images.unsplash.com/photo-1581578731117-104f2a41272c?q=80&w=2070&auto=format&fit=crop";

interface AuthProps {
  users: User[];
  onLogin: (user: User) => void;
  onRegister: (newUser: User) => void;
}

export default function Auth({ users, onLogin, onRegister }: AuthProps) {
  const [viewMode, setViewMode] = useState<'LOGIN' | 'REGISTER' | 'FORGOT_PASSWORD'>('LOGIN');
  const [authStep, setAuthStep] = useState<'FORM' | 'VERIFICATION'>('FORM');
  const [verificationCode, setVerificationCode] = useState(['', '', '', '']);
  const [confirmationResult, setConfirmationResult] = useState<any>(null);

  const recaptchaVerifierRef = useRef<any>(null);

  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [successMsg, setSuccessMsg] = useState('');
  const [loading, setLoading] = useState(false);
  const [isSimulationMode, setIsSimulationMode] = useState(false);
  const [highlightTermsError, setHighlightTermsError] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    city: 'Abidjan',
    password: '',
    confirmPassword: '',
    role: UserRole.CLIENT,
    address: '',
    idNumber: '',
    acceptTerms: false
  });

  const [selectedServices, setSelectedServices] = useState<ServiceCategory[]>([]);
  const [avatarPreview, setAvatarPreview] = useState<string | null>(null);
  const [avatarFile, setAvatarFile] = useState<File | null>(null);
  const [idCardRectoFile, setIdCardRectoFile] = useState<File | null>(null);
  const [idCardVersoFile, setIdCardVersoFile] = useState<File | null>(null);

  useEffect(() => {
    return () => {
      if (recaptchaVerifierRef.current) {
        try { recaptchaVerifierRef.current.clear(); } catch (e) {}
      }
    };
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const value = e.target.type === 'checkbox' ? (e.target as HTMLInputElement).checked : e.target.value;
    setFormData({ ...formData, [e.target.name]: value });
    setError('');
    if (e.target.name === 'acceptTerms') setHighlightTermsError(false);
  };

  const handleRoleSwitch = (newRole: UserRole) => {
      setFormData({ ...formData, role: newRole, acceptTerms: false });
      setSelectedServices([]);
      setError('');
  };

  const toggleService = (service: ServiceCategory) => {
    if (selectedServices.includes(service)) {
      setSelectedServices(selectedServices.filter(s => s !== service));
    } else {
      setSelectedServices([...selectedServices, service]);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>, type: 'AVATAR' | 'ID_RECTO' | 'ID_VERSO') => {
    const file = e.target.files?.[0];
    if (file) {
      if (type === 'AVATAR') {
          setAvatarFile(file);
          const reader = new FileReader();
          reader.onloadend = () => setAvatarPreview(reader.result as string);
          reader.readAsDataURL(file);
      } else if (type === 'ID_RECTO') {
          setIdCardRectoFile(file);
      } else if (type === 'ID_VERSO') {
          setIdCardVersoFile(file);
      }
    }
  };

  const handleCodeChange = (index: number, value: string) => {
      if (value.length > 1) return;
      const newCode = [...verificationCode];
      newCode[index] = value;
      setVerificationCode(newCode);
      if (value && index < 3) document.getElementById(`code-${index + 1}`)?.focus();
  };

  const setupRecaptcha = () => {
    if (recaptchaVerifierRef.current) {
        try { recaptchaVerifierRef.current.clear(); } catch (e) {}
        recaptchaVerifierRef.current = null;
    }
    const container = document.getElementById('recaptcha-container');
    if (container) container.innerHTML = '';

    try {
        const verifier = new RecaptchaVerifier(auth, 'recaptcha-container', {
            'size': 'invisible',
            'callback': () => {},
            'expired-callback': () => {
                 if (recaptchaVerifierRef.current) {
                    try { recaptchaVerifierRef.current.clear(); } catch(e){}
                    recaptchaVerifierRef.current = null;
                 }
            }
        });
        recaptchaVerifierRef.current = verifier;
        return verifier;
    } catch (e) {
        return null;
    }
  };

  const initiateAuth = async (e: React.FormEvent) => {
      e.preventDefault();
      setError('');
      setSuccessMsg('');
      setLoading(true);
      setIsSimulationMode(false);

      try {
          if (viewMode === 'REGISTER') {
             if (!formData.acceptTerms) {
                setHighlightTermsError(true); setLoading(false); return;
             }
             if (!avatarFile) throw new Error("Veuillez ajouter une photo de profil.");
          }

          if (viewMode === 'LOGIN') {
              const user = users.find(u => u.phone === formData.phone && u.password === formData.password);
              if (!user) throw new Error("Numéro de téléphone ou mot de passe incorrect.");
          } else {
              if (formData.password !== formData.confirmPassword) throw new Error("Les mots de passe ne correspondent pas.");
              if (formData.role === UserRole.PROVIDER && selectedServices.length === 0) throw new Error("Veuillez sélectionner au moins une compétence.");
              if (!formData.idNumber || !idCardRectoFile || !idCardVersoFile) throw new Error("La pièce d'identité (Numéro + Recto + Verso) est obligatoire.");
              const userExists = users.some(u => u.phone === formData.phone);
              if(userExists) throw new Error("Ce numéro de téléphone est déjà utilisé.");
          }

          const timeoutPromise = new Promise((_, reject) => 
              setTimeout(() => reject(new Error("TIMEOUT_RECAPTCHA")), 5000)
          );

          let appVerifier;
          try {
              appVerifier = setupRecaptcha();
              if (!appVerifier) throw new Error("internal-error-fallback");

              const phoneNumber = formData.phone.startsWith('+') ? formData.phone : `+225${formData.phone}`;

              const confirmation = await Promise.race([
                  signInWithPhoneNumber(auth, phoneNumber, appVerifier),
                  timeoutPromise
              ]);

              setConfirmationResult(confirmation);
              setAuthStep('VERIFICATION');
              setLoading(false);

          } catch (firebaseError: any) {
              console.warn("Firebase Auth Issue:", firebaseError);
              setIsSimulationMode(true);
              setAuthStep('VERIFICATION');
              setLoading(false);
              setSuccessMsg(`Mode Secours Activé. Code: 1234`);
              if (recaptchaVerifierRef.current) try { recaptchaVerifierRef.current.clear(); } catch(e){}
          }
      } catch (err: any) {
          setError(err.message);
          setLoading(false);
      }
  };

  const verifyAndSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      const code = verificationCode.join('');
      setLoading(true); setError('');

      try {
          if (isSimulationMode) {
              if (code !== '1234' && code !== '123456') throw new Error("Code incorrect (1234).");
          } else {
              if (!confirmationResult) throw new Error("Session expirée.");
              await confirmationResult.confirm(code);
          }

          if (viewMode === 'LOGIN') {
              const user = users.find(u => u.phone === formData.phone);
              if (user) onLogin(user);
          } else {
              const avatarUrl = avatarFile ? await uploadImage(avatarFile, `avatars/${Date.now()}_${formData.phone}`) : `https://ui-avatars.com/api/?name=${formData.name}`;
              const rectoUrl = idCardRectoFile ? await uploadImage(idCardRectoFile, `id_cards/${Date.now()}_recto`) : '';
              const versoUrl = idCardVersoFile ? await uploadImage(idCardVersoFile, `id_cards/${Date.now()}_verso`) : '';

              const newUser: User = {
                  id: `u${Date.now()}`,
                  name: formData.name,
                  email: formData.email,
                  phone: formData.phone,
                  password: formData.password,
                  role: formData.role,
                  address: formData.address,
                  city: formData.city,
                  avatarUrl: avatarUrl,
                  services: formData.role === UserRole.PROVIDER ? selectedServices : undefined,
                  verified: false,
                  walletBalance: 0,
                  createdAt: new Date().toISOString(),
                  idNumber: formData.idNumber,
                  idCardRecto: rectoUrl,
                  idCardVerso: versoUrl,
                  acceptTerms: true
              };
              onRegister(newUser);
          }
      } catch (err: any) {
          setError(err.message || "Code invalide.");
          setLoading(false);
      }
  };

  if (authStep === 'VERIFICATION') {
      return (
          <div className="min-h-screen flex items-center justify-center bg-gray-50 p-4 font-sans" style={{backgroundImage: `url('${BACKGROUND_IMAGE}')`, backgroundSize: 'cover'}}>
              <div className="absolute inset-0 bg-blue-900/60 backdrop-blur-sm"></div>
              <div className="bg-white p-8 rounded-3xl shadow-2xl w-full max-w-md relative z-10 animate-scale-in">
                  <div className="text-center mb-8">
                      <div className="bg-blue-100 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4 animate-bounce"><Smartphone className="text-blue-600" size={32} /></div>
                      <h2 className="text-2xl font-extrabold text-gray-900">Vérification</h2>
                      <p className="text-gray-500 mt-2 text-sm">Entrez le code envoyé au {formData.phone}</p>
                  </div>
                  {successMsg && <div className="bg-green-100 border border-green-400 text-green-700 px-4 py-3 rounded-xl mb-6 text-sm text-center font-bold">{successMsg}</div>}
                  {error && <div className="bg-red-50 border border-red-200 text-red-600 px-4 py-3 rounded-xl mb-6 text-sm flex items-center"><AlertCircle size={16} className="mr-2" />{error}</div>}
                  <form onSubmit={verifyAndSubmit}>
                      <div className="flex justify-center space-x-3 mb-8">
                          {verificationCode.map((digit, index) => (
                              <input key={index} id={`code-${index}`} type="text" maxLength={1} value={digit} onChange={(e) => handleCodeChange(index, e.target.value)} className="w-12 h-14 text-center text-2xl font-bold border-2 border-gray-300 rounded-xl focus:border-blue-500 focus:ring-2 outline-none" />
                          ))}
                      </div>
                      <button type="submit" disabled={loading} className="w-full bg-blue-600 text-white py-4 rounded-xl font-bold text-lg shadow-lg hover:bg-blue-700 transition-all flex justify-center items-center">
                          {loading ? <Loader2 className="animate-spin" /> : "Valider"}
                      </button>
                  </form>
                  <button onClick={() => setAuthStep('FORM')} className="w-full text-center mt-6 text-gray-500 text-sm hover:text-blue-600 font-medium">Retour</button>
              </div>
          </div>
      );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50 p-4 font-sans relative overflow-hidden">
        <style>{`.grecaptcha-badge { visibility: hidden !important; opacity: 0 !important; pointer-events: none !important; display: none !important; }`}</style>
        <div className="absolute inset-0 z-0"><img src={BACKGROUND_IMAGE} alt="Background" className="w-full h-full object-cover" /><div className="absolute inset-0 bg-blue-900/80 backdrop-blur-sm"></div></div>
        <div className="bg-white rounded-3xl shadow-2xl w-full max-w-lg relative z-10 overflow-hidden animate-scale-in flex flex-col max-h-[90vh]">
            <div className="pt-8 pb-6 px-8 text-center bg-white relative">
                 <div className="w-20 h-20 bg-gradient-to-br from-blue-600 to-blue-800 rounded-2xl flex items-center justify-center text-white font-bold text-3xl shadow-blue-200 shadow-xl mx-auto mb-4 animate-float">S<span className="text-orange-400">+</span></div>
                 <h1 className="text-3xl font-extrabold text-blue-900 tracking-tight">Servi<span className="text-orange-500">+</span></h1>
                 <p className="text-gray-500 font-medium mt-1">Votre service à domicile le plus efficace</p>
            </div>
            <div className="px-8 pb-8 overflow-y-auto custom-scrollbar flex-1">
                <div className="flex bg-gray-100 p-1 rounded-xl mb-6">
                    <button onClick={() => { setViewMode('LOGIN'); setError(''); }} className={`flex-1 py-3 text-sm font-bold rounded-lg transition-all ${viewMode === 'LOGIN' ? 'bg-white text-blue-900 shadow-sm' : 'text-gray-500'}`}>Connexion</button>
