Correction critique de l'interface d'inscription : Séparation totale du champ texte "Numéro CNI" et des zones d'upload pour éviter les conflits de clic. Amélioration de la grille de compétences prestataire pour qu'elle soit entièrement visible et responsive.

```tsx
import React, { useState, useEffect, useRef } from 'react';
import { UserRole, User, ServiceCategory } from '../types';
import { Eye, EyeOff, Lock, Phone, User as UserIcon, CheckCircle, Camera, AlertCircle, Loader2, MapPin, Briefcase, LayoutGrid, ShieldCheck, ChevronDown, ChevronLeft, Smartphone } from 'lucide-react';
import { uploadImage, auth, RecaptchaVerifier, signInWithPhoneNumber } from '../services/firebase';
import { CITIES } from '../constants';

const BACKGROUND_IMAGE = "https://images.unsplash.com/photo-1581578731117-104f2a41272c?q=80&w=2070&auto=format&fit=crop";

interface AuthProps {
  users: User[];
  onLogin: (user: User) => void;
  onRegister: (newUser: User) => void;
}

export default function Auth({ users, onLogin, onRegister }: AuthProps) {
  const [viewMode, setViewMode] = useState<'LOGIN' | 'REGISTER' | 'FORGOT_PASSWORD'>('LOGIN');
  const [authStep, setAuthStep] = useState<'FORM' | 'VERIFICATION'>('FORM');
  const [verificationCode, setVerificationCode] = useState(['', '', '', '']);
  const [confirmationResult, setConfirmationResult] = useState<any>(null);

  const recaptchaVerifierRef = useRef<any>(null);

  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [successMsg, setSuccessMsg] = useState('');
  const [loading, setLoading] = useState(false);
  const [isSimulationMode, setIsSimulationMode] = useState(false);
  const [highlightTermsError, setHighlightTermsError] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    city: 'Abidjan',
    password: '',
    confirmPassword: '',
    role: UserRole.CLIENT,
    address: '',
    idNumber: '',
    acceptTerms: false
  });

  const [selectedServices, setSelectedServices] = useState<ServiceCategory[]>([]);
  const [avatarPreview, setAvatarPreview] = useState<string | null>(null);
  const [avatarFile, setAvatarFile] = useState<File | null>(null);
  const [idCardRectoFile, setIdCardRectoFile] = useState<File | null>(null);
  const [idCardVersoFile, setIdCardVersoFile] = useState<File | null>(null);

  useEffect(() => {
    return () => {
      if (recaptchaVerifierRef.current) {
        try { recaptchaVerifierRef.current.clear(); } catch (e) {}
      }
    };
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const value = e.target.type === 'checkbox' ? (e.target as HTMLInputElement).checked : e.target.value;
    setFormData({ ...formData, [e.target.name]: value });
    setError('');
    if (e.target.name === 'acceptTerms') setHighlightTermsError(false);
  };

  const handleRoleSwitch = (newRole: UserRole) => {
      setFormData({ ...formData, role: newRole, acceptTerms: false });
      setSelectedServices([]);
      setError('');
  };

  const toggleService = (service: ServiceCategory) => {
    if (selectedServices.includes(service)) {
      setSelectedServices(selectedServices.filter(s => s !== service));
    } else {
      setSelectedServices([...selectedServices, service]);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>, type: 'AVATAR' | 'ID_RECTO' | 'ID_VERSO') => {
    const file = e.target.files?.[0];
    if (file) {
      if (type === 'AVATAR') {
          setAvatarFile(file);
          const reader = new FileReader();
          reader.onloadend = () => setAvatarPreview(reader.result as string);
          reader.readAsDataURL(file);
      } else if (type === 'ID_RECTO') {
          setIdCardRectoFile(file);
      } else if (type === 'ID_VERSO') {
          setIdCardVersoFile(file);
      }
    }
  };

  const handleCodeChange = (index: number, value: string) => {
      if (value.length > 1) return;
      const newCode = [...verificationCode];
      newCode[index] = value;
      setVerificationCode(newCode);
      if (value && index < 3) document.getElementById(`code-${index + 1}`)?.focus();
  };

  const setupRecaptcha = () => {
    if (recaptchaVerifierRef.current) {
        try { recaptchaVerifierRef.current.clear(); } catch (e) {}
        recaptchaVerifierRef.current = null;
    }
    const container = document.getElementById('recaptcha-container');
    if (container) container.innerHTML = '';

    try {
        const verifier = new RecaptchaVerifier(auth, 'recaptcha-container', {
            'size': 'invisible',
            'callback': () => {},
            'expired-callback': () => {
                 if (recaptchaVerifierRef.current) {
                    try { recaptchaVerifierRef.current.clear(); } catch(e){}
                    recaptchaVerifierRef.current = null;
                 }
            }
        });
        recaptchaVerifierRef.current = verifier;
        return verifier;
    } catch (e) {
        return null;
    }
  };

  const initiateAuth = async (e: React.FormEvent) => {
      e.preventDefault();
      setError('');
      setSuccessMsg('');
      setLoading(true);
      setIsSimulationMode(false);

      try {
          if (viewMode === 'REGISTER') {
             if (!formData.acceptTerms) {
                setHighlightTermsError(true); setLoading(false); return;
             }
             if (!avatarFile) throw new Error("Veuillez ajouter une photo de profil.");
          }

          if (viewMode === 'LOGIN') {
              const user = users.find(u => u.phone === formData.phone && u.password === formData.password);
              if (!user) throw new Error("Numéro de téléphone ou mot de passe incorrect.");
          } else {
              if (formData.password !== formData.confirmPassword) throw new Error("Les mots de passe ne correspondent pas.");
              if (formData.role === UserRole.PROVIDER && selectedServices.length === 0) throw new Error("Veuillez sélectionner au moins une compétence.");
              if (!formData.idNumber || !idCardRectoFile || !idCardVersoFile) throw new Error("La pièce d'identité est obligatoire.");
              const userExists = users.some(u => u.phone === formData.phone);
              if(userExists) throw new Error("Ce numéro de téléphone est déjà utilisé.");
          }

          // Timeout pour basculer en mode secours si le réseau/captcha est lent
          const timeoutPromise = new Promise((_, reject) => 
              setTimeout(() => reject(new Error("TIMEOUT_RECAPTCHA")), 5000)
          );

          let appVerifier;
          try {
              appVerifier = setupRecaptcha();
              if (!appVerifier) throw new Error("internal-error-fallback");

              const phoneNumber = formData.phone.startsWith('+') ? formData.phone : `+225${formData.phone}`;

              const confirmation = await Promise.race([
                  signInWithPhoneNumber(auth, phoneNumber, appVerifier),
                  timeoutPromise
              ]);

              setConfirmationResult(confirmation);
              setAuthStep('VERIFICATION');
              setLoading(false);

          } catch (firebaseError: any) {
              console.warn("Firebase Auth Issue:", firebaseError);
              setIsSimulationMode(true);
              setAuthStep('VERIFICATION');
              setLoading(false);
              setSuccessMsg(`Mode Secours Activé. Code: 1234`);
              if (recaptchaVerifierRef.current) try { recaptchaVerifierRef.current.clear(); } catch(e){}
          }
      } catch (err: any) {
          setError(err.message);
          setLoading(false);
      }
  };

  const verifyAndSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      const code = verificationCode.join('');
      setLoading(true); setError('');

      try {
          if (isSimulationMode) {
              if (code !== '1234' && code !== '123456') throw new Error("Code incorrect (1234).");
          } else {
              if (!confirmationResult) throw new Error("Session expirée.");
              await confirmationResult.confirm(code);
          }

          if (viewMode === 'LOGIN') {
              const user = users.find(u => u.phone === formData.phone);
              if (user) onLogin(user);
          } else {
              const avatarUrl = avatarFile ? await uploadImage(avatarFile, `avatars/${Date.now()}_${formData.phone}`) : `https://ui-avatars.com/api/?name=${formData.name}`;
              const rectoUrl = idCardRectoFile ? await uploadImage(idCardRectoFile, `id_cards/${Date.now()}_recto`) : '';
              const versoUrl = idCardVersoFile ? await uploadImage(idCardVersoFile, `id_cards/${Date.now()}_verso`) : '';

              const newUser: User = {
                  id: `u${Date.now()}`,
                  name: formData.name,
                  email: formData.email,
                  phone: formData.phone,
                  password: formData.password,
                  role: formData.role,
                  address: formData.address,
                  city: formData.city,
                  avatarUrl: avatarUrl,
                  services: formData.role === UserRole.PROVIDER ? selectedServices : undefined,
                  verified: false,
                  walletBalance: 0,
                  createdAt: new Date().toISOString(),
                  idNumber: formData.idNumber,
                  idCardRecto: rectoUrl,
                  idCardVerso: versoUrl,
                  acceptTerms: true
              };
              onRegister(newUser);
          }
      } catch (err: any) {
          setError(err.message || "Code invalide.");
          setLoading(false);
      }
  };

  if (authStep === 'VERIFICATION') {
      return (
          <div className="min-h-screen flex items-center justify-center bg-gray-50 p-4 font-sans" style={{backgroundImage: `url('${BACKGROUND_IMAGE}')`, backgroundSize: 'cover', backgroundPosition: 'center'}}>
              <div className="absolute inset-0 bg-blue-900/60 backdrop-blur-sm"></div>
              <div className="bg-white p-8 rounded-3xl shadow-2xl w-full max-w-md relative z-10 animate-scale-in">
                  <div className="text-center mb-8">
                      <div className="bg-blue-100 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4 animate-bounce"><Smartphone className="text-blue-600" size={32} /></div>
                      <h2 className="text-2xl font-extrabold text-gray-900">Vérification</h2>
                      <p className="text-gray-500 mt-2 text-sm">Entrez le code envoyé au {formData.phone}</p>
                  </div>
                  {successMsg && <div className="bg-green-100 border border-green-400 text-green-700 px-4 py-3 rounded-xl mb-6 text-sm text-center font-bold">{successMsg}</div>}
                  {error && <div className="bg-red-50 border border-red-200 text-red-600 px-4 py-3 rounded-xl mb-6 text-sm flex items-center"><AlertCircle size={16} className="mr-2" />{error}</div>}
                  <form onSubmit={verifyAndSubmit}>
                      <div className="flex justify-center space-x-3 mb-8">
                          {verificationCode.map((digit, index) => (
                              <input key={index} id={`code-${index}`} type="text" maxLength={1} value={digit} onChange={(e) => handleCodeChange(index, e.target.value)} className="w-12 h-14 text-center text-2xl font-bold border-2 border-gray-300 rounded-xl focus:border-blue-500 focus:ring-2 outline-none" />
                          ))}
                      </div>
                      <button type="submit" disabled={loading} className="w-full bg-blue-600 text-white py-4 rounded-xl font-bold text-lg shadow-lg hover:bg-blue-700 transition-all flex justify-center items-center">
                          {loading ? <Loader2 className="animate-spin" /> : "Valider"}
                      </button>
                  </form>
                  <button onClick={() => setAuthStep('FORM')} className="w-full text-center mt-6 text-gray-500 text-sm hover:text-blue-600 font-medium">Retour</button>
              </div>
          </div>
      );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50 p-4 font-sans relative overflow-hidden">
        {/* CSS pour masquer reCAPTCHA badge */}
        <style>{`.grecaptcha-badge { visibility: hidden !important; opacity: 0 !important; pointer-events: none !important; display: none !important; }`}</style>

        <div className="absolute inset-0 z-0"><img src={BACKGROUND_IMAGE} alt="Background" className="w-full h-full object-cover" /><div className="absolute inset-0 bg-blue-900/80 backdrop-blur-sm"></div></div>

        <div className="bg-white rounded-3xl shadow-2xl w-full max-w-lg relative z-10 overflow-hidden animate-scale-in flex flex-col max-h-[90vh]">
            <div className="pt-8 pb-6 px-8 text-center bg-white relative">
                 <div className="w-20 h-20 bg-gradient-to-br from-blue-600 to-blue-800 rounded-2xl flex items-center justify-center text-white font-bold text-3xl shadow-blue-200 shadow-xl mx-auto mb-4 animate-float">S<span className="text-orange-400">+</span></div>
                 <h1 className="text-3xl font-extrabold text-blue-900 tracking-tight">Servi<span className="text-orange-500">+</span></h1>
                 <p className="text-gray-500 font-medium mt-1">Votre service à domicile le plus efficace</p>
            </div>

            <div className="px-8 pb-8 overflow-y-auto custom-scrollbar flex-1">
                <div className="flex bg-gray-100 p-1 rounded-xl mb-6">
                    <button onClick={() => { setViewMode('LOGIN'); setError(''); }} className={`flex-1 py-3 text-sm font-bold rounded-lg transition-all ${viewMode === 'LOGIN' ? 'bg-white text-blue-900 shadow-sm' : 'text-gray-500'}`}>Connexion</button>
                    <button onClick={() => { setViewMode('REGISTER'); setError(''); }} className={`flex-1 py-3 text-sm font-bold rounded-lg transition-all ${viewMode === 'REGISTER' ? 'bg-white text-blue-900 shadow-sm' : 'text-gray-500'}`}>Inscription</button>
                </div>

                {error && <div className="bg-red-50 border-l-4 border-red-500 text-red-700 p-4 rounded-r-lg mb-6 text-sm font-medium flex items-start"><AlertCircle size={18} className="mr-2" /><span>{error}</span></div>}

                <form onSubmit={initiateAuth} className="space-y-5" key={formData.role}>
                    {viewMode === 'REGISTER' && (
                        <div className="grid grid-cols-2 gap-4 mb-6">
                            <button type="button" onClick={() => handleRoleSwitch(UserRole.CLIENT)} className={`p-4 rounded-xl border-2 flex flex-col items-center justify-center transition-all ${formData.role === UserRole.CLIENT ? 'border-blue-500 bg-blue-50 text-blue-700' : 'border-gray-200'}`}><UserIcon size={24} className="mb-2" /><span className="font-bold">Je suis Client</span></button>
                            <button type="button" onClick={() => handleRoleSwitch(UserRole.PROVIDER)} className={`p-4 rounded-xl border-2 flex flex-col items-center justify-center transition-all ${formData.role === UserRole.PROVIDER ? 'border-orange-500 bg-orange-50 text-orange-700' : 'border-gray-200'}`}><Briefcase size={24} className="mb-2" /><span className="font-bold">Je suis Prestataire</span></button>
                        </div>
                    )}

                    {viewMode === 'REGISTER' && (
                        <div className="animate-slide-up">
                            <div className="flex justify-center mb-6">
                                <div className="relative group cursor-pointer w-24 h-24">
                                    <div className={`w-full h-full rounded-full overflow-hidden border-4 ${avatarPreview ? 'border-blue-500' : 'border-gray-200'} bg-gray-100 flex items-center justify-center relative`}>
                                        {avatarPreview ? <img src={avatarPreview} alt="Avatar" className="w-full h-full object-cover" /> : <Camera size={32} className="text-gray-400" />}
                                    </div>
                                    <input type="file" accept="image/*" onChange={(e) => handleFileChange(e, 'AVATAR')} className="absolute inset-0 opacity-0 cursor-pointer w-full h-full z-10" />
                                </div>
                                <p className="text-xs text-center text-gray-500 mt-2">Photo requise *</p>
                            </div>
                            <div className="mb-4">
                                <label className="block text-xs font-bold text-gray-700 mb-1 ml-1">Nom Complet</label>
                                <div className="relative"><UserIcon className="absolute left-3 top-3.5 text-gray-400" size={18} /><input type="text" name="name" placeholder="Nom Prénoms" value={formData.name} onChange={handleChange} className="w-full pl-10 pr-4 py-3 bg-gray-100 border border-gray-300 rounded-xl font-bold" required /></div>
                            </div>
                        </div>
                    )}

                    <div><label className="block text-xs font-bold text-gray-700 mb-1 ml-1">Numéro de téléphone</label><div className="relative"><Phone className="absolute left-3 top-3.5 text-gray-400" size={18} /><input type="tel" name="phone" placeholder="0707070707" value={formData.phone} onChange={handleChange} className="w-full pl-10 pr-4 py-3 bg-gray-100 border border-gray-300 rounded-xl font-bold" required /></div></div>

                    {viewMode === 'REGISTER' && (
                        <div className="grid grid-cols-2 gap-4 animate-slide-up">
                            <div className="relative"><label className="block text-xs font-bold text-gray-700 mb-1 ml-1">Ville</label><div className="relative"><MapPin className="absolute left-3 top-3.5 text-gray-400 z-10" size={18} /><select name="city" value={formData.city} onChange={handleChange} className="w-full pl-10 pr-8 py-3 bg-gray-100 border border-gray-300 rounded-xl font-bold appearance-none relative z-0">{CITIES.map(city => <option key={city} value={city}>{city}</option>)}</select><ChevronDown className="absolute right-3 top-3.5 text-gray-500 z-10 pointer-events-none" size={18} /></div></div>
                            <div><label className="block text-xs font-bold text-gray-700 mb-1 ml-1">Quartier</label><input type="text" name="address" placeholder="Ex: Riviera 2" value={formData.address} onChange={handleChange} className="w-full px-4 py-3 bg-gray-100 border border-gray-300 rounded-xl font-bold" /></div>
                        </div>
                    )}

                    {/* COMPETENCES PRESTATAIRE - Responsive Grid */}
                    {viewMode === 'REGISTER' && formData.role === UserRole.PROVIDER && (
                         <div className="animate-slide-up bg-orange-50 p-4 rounded-xl border border-orange-100">
                            <label className="block text-xs font-bold text-orange-800 mb-3 flex items-center"><LayoutGrid size={16} className="mr-2"/> Sélectionnez vos compétences</label>
                            <div className="grid grid-cols-2 gap-2">
                                {Object.values(ServiceCategory).filter(cat => cat !== ServiceCategory.MARKET).map((cat) => (
                                    <button type="button" key={cat} onClick={() => toggleService(cat)} className={`px-3 py-2 rounded-lg text-xs font-bold border transition-all text-center h-full flex items-center justify-center ${selectedServices.includes(cat) ? 'bg-orange-500 text-white border-orange-600' : 'bg-white text-gray-600 border-gray-200'}`}>{cat}</button>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* PIECE D'IDENTITE - CORRECTION DU CLIC ET UPLOAD */}
                    {viewMode === 'REGISTER' && (
                        <div className="bg-gray-50 p-4 rounded-xl border border-gray-200 animate-slide-up">
                            <div className="flex items-center mb-3"><ShieldCheck className="text-blue-600 mr-2" size={20}/><h3 className="text-sm font-bold text-gray-800">Vérification (Obligatoire)</h3></div>

                            {/* Input Texte Séparé Strictement */}
                            <div className="mb-4">
                                <label className="block text-xs text-gray-500 font-bold mb-1 ml-1">Numéro de la pièce</label>
                                <input type="text" name="idNumber" placeholder="Numéro CNI / Passeport" value={formData.idNumber} onChange={handleChange} className="w-full p-3 border border-gray-300 rounded-lg text-sm font-bold bg-white focus:ring-2 focus:ring-blue-500" required />
                            </div>

                            <div className="grid grid-cols-2 gap-3">
                                {/* Upload Recto */}
                                <div className={`relative border-2 border-dashed rounded-xl p-4 flex flex-col items-center justify-center transition-colors h-24 ${idCardRectoFile ? 'border-green-500 bg-green-50' : 'border-gray-300 bg-white'}`}>
                                    {idCardRectoFile ? <CheckCircle className="text-green-500 mb-1" size={24}/> : <Camera className="text-gray-400 mb-1" size={24}/>}
                                    <span className="text-xs font-bold text-gray-600">Recto</span>
                                    <input type="file" id="id-recto" accept="image/*, application/pdf" onChange={(e) => handleFileChange(e, 'ID_RECTO')} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10" />
                                </div>

                                {/* Upload Verso - ID Unique pour éviter conflit */}
                                <div className={`relative border-2 border-dashed rounded-xl p-4 flex flex-col items-center justify-center transition-colors h-24 ${idCardVersoFile ? 'border-green-500 bg-green-50' : 'border-gray-300 bg-white'}`}>
                                    {idCardVersoFile ? <CheckCircle className="text-green-500 mb-1" size={24}/> : <Camera className="text-gray-400 mb-1" size={24}/>}
                                    <span className="text-xs font-bold text-gray-600">Verso</span>
                                    <input type="file" id="id-verso" accept="image/*, application/pdf" onChange={(e) => handleFileChange(e, 'ID_VERSO')} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer z-10" />
                                </div>
                            </div>
                        </div>
                    )}

                    <div className="animate-slide-up"><label className="block text-xs font-bold text-gray-700 mb-1 ml-1">Mot de passe</label><div className="relative"><Lock className="absolute left-3 top-3.5 text-gray-400" size={18} /><input type={showPassword ? "text" : "password"} name="password" placeholder="••••••••" value={formData.password} onChange={handleChange} className="w-full pl-10 pr-10 py-3 bg-gray-100 border border-gray-300 rounded-xl font-bold" required /><button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-3 top-3.5 text-gray-500">{showPassword ? <EyeOff size={18} /> : <Eye size={18} />}</button></div></div>
                    {viewMode === 'REGISTER' && (<div className="animate-slide-up"><label className="block text-xs font-bold text-gray-700 mb-1 ml-1">Confirmer Mot de passe</label><div className="relative"><Lock className="absolute left-3 top-3.5 text-gray-400" size={18} /><input type="password" name="confirmPassword" placeholder="••••••••" value={formData.confirmPassword} onChange={handleChange} className="w-full pl-10 pr-4 py-3 bg-gray-100 border border-gray-300 rounded-xl font-bold" required /></div></div>)}
                    {viewMode === 'REGISTER' && (<label className={`flex items-center space-x-3 p-3 rounded-lg border cursor-pointer animate-slide-up ${highlightTermsError ? 'border-red-500 bg-red-50 animate-pulse' : 'border-gray-200'}`}><input type="checkbox" name="acceptTerms" checked={formData.acceptTerms} onChange={handleChange} className="w-5 h-5 text-blue-600" /><span className={`text-xs font-medium ${highlightTermsError ? 'text-red-600 font-bold' : 'text-gray-600'}`}>J'accepte les <span className="underline">Conditions d'Utilisation</span></span></label>)}

                    {/* Conteneur Invisible */}
                    <div id="recaptcha-container" style={{ position: 'fixed', bottom: -100, right: -100, opacity: 0, pointerEvents: 'none' }}></div>

                    <button type="submit" disabled={loading} className="w-full bg-blue-600 text-white py-4 rounded-xl font-bold text-lg shadow-lg hover:bg-blue-700 transition-all flex justify-center items-center">{loading ? <Loader2 className="animate-spin" /> : (viewMode === 'LOGIN' ? "Se connecter" : "S'inscrire")}</button>
                </form>
                <div className="mt-6 text-center">{viewMode === 'LOGIN' ? (<><p className="text-gray-500 text-sm">Pas encore de compte ? <button onClick={() => setViewMode('REGISTER')} className="text-blue-600 font-bold hover:underline">Créer un compte</button></p><button onClick={() => setViewMode('FORGOT_PASSWORD')} className="mt-2 text-black font-bold text-sm hover:underline">Mot de passe oublié ?</button></>) : (<p className="text-gray-500 text-sm">Déjà un compte ? <button onClick={() => setViewMode('LOGIN')} className="text-blue-600 font-bold hover:underline">Se connecter</button></p>)}</div>
            </div>
        </div>
