## src/components/ProviderDashboard.tsx

Amélioration de la section profil pour utiliser une grille responsive (grid-cols-2) pour les compétences, assurant que tout est visible sur les écrans mobiles.

```tsx
import React, { useState } from 'react';
import { User, Mission, MissionStatus, ServiceCategory, Transaction } from '../types';
import { SERVICE_ICONS, CITIES } from '../constants';
import { MapPin, Clock, CheckCircle, AlertTriangle, Star, Calendar, Phone, Navigation, User as UserIcon, Save, Wallet, LayoutGrid, DollarSign, ChevronDown, Camera, List, ShoppingBag } from 'lucide-react';

interface ProviderDashboardProps {
  currentUser: User;
  missions: Mission[];
  users: User[];
  transactions: Transaction[];
  onUpdateMissionStatus: (missionId: string, status: MissionStatus, providerId?: string, estimation?: { arrivalTime: string, distance: number }) => void;
  onDisputeMission: (missionId: string, reason: string) => void;
  onRateClient: (missionId: string, rating: number, comment: string) => void;
  onUpdateUser: (data: Partial<User>) => void;
  onRequestWithdrawal: (amount: number, method: string) => void;
}

export default function ProviderDashboard({ currentUser, missions, users, transactions, onUpdateMissionStatus, onDisputeMission, onRateClient, onUpdateUser, onRequestWithdrawal }: ProviderDashboardProps) {
  const [activeTab, setActiveTab] = useState<'marketplace' | 'my-missions' | 'wallet' | 'profile'>('marketplace');

  // Profile State
  const [profileForm, setProfileForm] = useState({
    name: currentUser.name,
    phone: currentUser.phone,
    address: currentUser.address || '',
    city: currentUser.city || 'Abidjan',
    password: currentUser.password || ''
  });
  const [selectedServices, setSelectedServices] = useState<ServiceCategory[]>(currentUser.services || []);
  const [newAvatar, setNewAvatar] = useState<string | null>(null);

  // Wallet State
  const [withdrawalAmount, setWithdrawalAmount] = useState<number>(0);

  // Data Filtering
  const myMissions = missions.filter(m => m.providerId === currentUser.id);
  const activeMyMissionsCount = myMissions.filter(m => [MissionStatus.ACCEPTED, MissionStatus.IN_PROGRESS].includes(m.status)).length;

  const availableMissions = missions.filter(m => m.status === MissionStatus.PENDING && !m.providerId && (!currentUser.city || m.city === currentUser.city) && (!currentUser.services || currentUser.services.includes(m.category)));

  const totalEarnings = myMissions.filter(m => m.status === MissionStatus.COMPLETED).reduce((sum, m) => sum + m.providerAmount, 0);
  const withdrawn = transactions.filter(t => t.type === 'PAYOUT' && t.userId === currentUser.id).reduce((sum, t) => sum + t.amount, 0);
  const balance = Math.max(0, totalEarnings - withdrawn);

  // Modal State
  const [selectedMissionId, setSelectedMissionId] = useState<string | null>(null);
  const [modalType, setModalType] = useState<'DISPUTE' | 'RATING' | null>(null);
  const [inputText, setInputText] = useState('');
  const [ratingValue, setRatingValue] = useState(5);

  const openRating = (id: string) => {
    setSelectedMissionId(id);
    setModalType('RATING');
    setInputText('');
    setRatingValue(5);
  };

  const submitModal = () => {
    if (!selectedMissionId) return;
    if (modalType === 'RATING') {
      onRateClient(selectedMissionId, ratingValue, inputText);
    }
    setModalType(null);
    setSelectedMissionId(null);
  };

  const handleAcceptMission = (missionId: string) => {
      // Simulate GPS Calculation
      const arrival = new Date(); arrival.setMinutes(arrival.getMinutes() + 30);
      onUpdateMissionStatus(missionId, MissionStatus.ACCEPTED, currentUser.id, { arrivalTime: arrival.toISOString(), distance: 5 });
      setActiveTab('my-missions');
  };

  const handleProfileSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      onUpdateUser({
          ...profileForm,
          services: selectedServices,
          avatarUrl: newAvatar || currentUser.avatarUrl
      });
      alert("✅ Profil mis à jour avec succès !");
  };

  const toggleService = (service: ServiceCategory) => {
      if (selectedServices.includes(service)) {
          setSelectedServices(selectedServices.filter(s => s !== service));
      } else {
          setSelectedServices([...selectedServices, service]);
      }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onloadend = () => setNewAvatar(reader.result as string);
          reader.readAsDataURL(file);
      }
  };

  const renderModal = () => {
    if (!modalType) return null;
    return (
      <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4 backdrop-blur-sm">
        <div className="bg-white rounded-2xl p-6 w-full max-w-md animate-scale-in shadow-2xl">
          <h3 className="text-xl font-bold mb-4 text-blue-600">Noter le client</h3>
          <div className="flex justify-center space-x-2 mb-4">
              {[1, 2, 3, 4, 5].map((star) => (
                <button key={star} onClick={() => setRatingValue(star)} className={`transition-transform hover:scale-125 ${star <= ratingValue ? 'text-yellow-400' : 'text-gray-300'}`}>
                  <Star size={32} fill="currentColor" />
                </button>
              ))}
          </div>
          <textarea value={inputText} onChange={(e) => setInputText(e.target.value)} className="w-full border border-gray-300 rounded-lg p-3 mb-4" rows={3} placeholder="Commentaire..." />
          <button onClick={submitModal} className="w-full bg-blue-600 text-white py-2 rounded-lg font-bold">Envoyer</button>
          <button onClick={() => setModalType(null)} className="w-full text-gray-500 py-2 mt-2">Annuler</button>
        </div>
      </div>
    );
  };

  const renderMarketplace = () => (
      <div className="space-y-4">
          {availableMissions.map(m => (
              <div key={m.id} className="bg-white p-6 rounded-2xl shadow-sm hover-card border border-gray-100">
                  <div className="flex justify-between items-start">
                      <div>
                          <h3 className="font-bold text-lg text-gray-900">{m.title}</h3>
                          <div className="flex items-center text-gray-500 text-sm mt-1">
                              <MapPin size={14} className="mr-1"/> {m.location} ({m.city})
                          </div>
                      </div>
                      <div className="text-right">
                          <span className="block text-green-600 font-bold text-xl">{m.providerAmount.toLocaleString()} F</span>
                          <span className="text-xs text-gray-400">Net vendeur</span>
                      </div>
                  </div>

                  <div className="bg-gray-50 p-3 rounded-lg mt-3 text-sm text-gray-600">
                      {m.category === ServiceCategory.MARKET ? (
                          <div className="flex items-center"><ShoppingBag size={14} className="mr-2"/> Commande de marché ({m.marketItems?.length} articles)</div>
                      ) : (
                          <p>{m.description.substring(0, 100)}...</p>
                      )}
                  </div>

                  <button onClick={() => handleAcceptMission(m.id)} className="w-full mt-4 bg-blue-600 text-white py-3 rounded-xl font-bold hover:bg-blue-700 transition-colors shadow-md">
                      Accepter la mission
                  </button>
              </div>
          ))}
          {availableMissions.length === 0 && (
              <div className="text-center py-12 bg-white rounded-2xl border border-dashed border-gray-300">
                  <p className="text-gray-500">Aucune mission disponible dans votre zone.</p>
              </div>
          )}
      </div>
  );

  const renderMyMissions = () => (
      <div className="space-y-6">
          {myMissions.map(m => {
              // Récupérer les infos du client associé à la mission
              const client = users.find(u => u.id === m.clientId);
              const isAccepted = m.status === MissionStatus.ACCEPTED || m.status === MissionStatus.IN_PROGRESS;

              return (
                  <div key={m.id} className="bg-white p-6 rounded-2xl shadow-sm border-l-4 border-blue-500 animate-slide-up">
                      <div className="flex justify-between items-center mb-4">
                          <div>
                              <h3 className="font-bold text-lg">{m.title}</h3>
                              <p className="text-xs text-gray-400">Commande #{m.id}</p>
                          </div>
                          <span className={`px-3 py-1 rounded-full text-xs font-bold ${
                              m.status === MissionStatus.COMPLETED ? 'bg-green-100 text-green-800' : 'bg-blue-100 text-blue-800'
                          }`}>
                              {m.status}
                          </span>
                      </div>

                      {/* --- CLIENT INFO SECTION (Visible only if Accepted) --- */}
                      {isAccepted && client ? (
                          <div className="bg-blue-50 p-4 rounded-xl border border-blue-100 mb-4">
                              <h4 className="font-bold text-blue-900 mb-3 flex items-center">
                                  <UserIcon size={16} className="mr-2"/> Informations Client
                              </h4>

                              <div className="flex justify-between items-center mb-3">
                                  <div>
                                      <p className="font-bold text-gray-900">{client.name}</p>
                                      <p className="text-sm text-gray-600 flex items-center mt-1">
                                          <MapPin size={14} className="mr-1"/> {m.location} ({m.city})
                                      </p>
                                  </div>
                                  <div className="flex space-x-2">
                                      <a href={`tel:${client.phone}`} className="bg-green-500 hover:bg-green-600 text-white p-2 rounded-full shadow-sm" title="Appeler">
                                          <Phone size={20} />
                                      </a>
                                      <a 
                                          href={`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(m.location + ' ' + m.city)}`} 
                                          target="_blank" 
                                          rel="noreferrer"
                                          className="bg-blue-500 hover:bg-blue-600 text-white p-2 rounded-full shadow-sm" 
                                          title="Y aller (GPS)"
                                      >
                                          <Navigation size={20} />
                                      </a>
                                  </div>
                              </div>

                              <div className="bg-white p-3 rounded-lg border border-blue-100">
                                  <h5 className="text-xs font-bold text-gray-500 uppercase mb-2">Contenu de la mission</h5>
                                  {m.category === ServiceCategory.MARKET && m.marketItems ? (
                                      <div className="space-y-1">
                                          {m.marketItems.map((item, idx) => (
                                              <div key={idx} className="flex justify-between text-sm border-b border-gray-100 last:border-0 pb-1 mb-1">
                                                  <span>- {item.name}</span>
                                                  <span className="font-bold text-gray-600">{item.price} F</span>
                                              </div>
                                          ))}
                                          <div className="text-right text-xs text-orange-600 font-bold mt-2">
                                              Budget courses prépayé par client.
                                          </div>
                                      </div>
                                  ) : m.category === ServiceCategory.LAUNDRY ? (
                                      <div>
                                          <p className="text-sm font-medium">Quantité : <span className="font-bold">{m.quantity} pièces</span></p>
                                          <p className="text-xs italic text-gray-500 mt-1">Instructions: "{m.description}"</p>
                                      </div>
                                  ) : (
                                      <p className="text-sm text-gray-700">"{m.description}"</p>
                                  )}
                              </div>
                          </div>
                      ) : (
                          <div className="mb-4 text-sm text-gray-500">
                              <p><MapPin size={14} className="inline mr-1"/> Zone : {m.city}</p>
                              <p className="mt-1">Détails masqués. Acceptez la mission pour voir les coordonnées.</p>
                          </div>
                      )}

                      <div className="mt-4 flex gap-2">
                          {m.status === MissionStatus.ACCEPTED && (
                              <button onClick={() => onUpdateMissionStatus(m.id, MissionStatus.IN_PROGRESS)} className="flex-1 bg-blue-600 text-white py-3 rounded-xl font-bold hover:bg-blue-700 shadow-md transition-transform active:scale-95">
                                  Commencer la mission
                              </button>
                          )}
                          {m.status === MissionStatus.IN_PROGRESS && (
                              <button onClick={() => onUpdateMissionStatus(m.id, MissionStatus.COMPLETED)} className="flex-1 bg-green-600 text-white py-3 rounded-xl font-bold hover:bg-green-700 shadow-md transition-transform active:scale-95 flex items-center justify-center">
                                  <CheckCircle size={18} className="mr-2"/> Terminer
                              </button>
                          )}
                          {m.status === MissionStatus.COMPLETED && !m.providerRating && (
                              <button onClick={() => openRating(m.id)} className="flex-1 bg-yellow-100 text-yellow-700 py-3 rounded-xl font-bold hover:bg-yellow-200 transition-colors">
                                  <Star size={18} className="inline mr-2"/> Noter le client
                              </button>
