                          {m.status === MissionStatus.COMPLETED && m.providerRating && (
                              <div className="flex-1 bg-green-50 text-green-700 py-3 rounded-xl font-bold text-center border border-green-100 flex justify-center items-center">
                                  <div className="flex mr-2">
