                            return (
                                <button
                                    key={cat}
                                    type="button"
                                    onClick={() => toggleService(cat)}
                                    className={`flex items-center justify-between p-3 rounded-xl border-2 transition-all transform hover:scale-[1.02] text-left h-full ${
                                        isSelected 
                                        ? 'border-blue-500 bg-blue-50 shadow-md' 
                                        : 'border-gray-100 bg-white text-gray-400 hover:border-gray-200'
                                    }`}
                                >
                                    <div className="flex items-center min-w-0">
                                        <div className={`p-2 rounded-full mr-2 flex-shrink-0 ${isSelected ? 'bg-blue-500 text-white' : 'bg-gray-100 text-gray-400'}`}>
                                            <Icon size={16} />
                                        </div>
                                        <span className={`text-xs font-bold truncate ${isSelected ? 'text-blue-900' : 'text-gray-500'}`}>{cat}</span>
                                    </div>
                                    {isSelected && <CheckCircle size={16} className="text-blue-500 flex-shrink-0 ml-1"/>}
                                </button>
                            );
                        })}
                    </div>
                  </div>
              </div>

              <button 
                  type="submit"
                  className="w-full bg-blue-600 text-white py-3 rounded-xl font-bold shadow-lg hover:bg-blue-700 transition-all flex items-center justify-center transform hover:scale-[1.02] active:scale-[0.98]"
              >
                  <Save size={20} className="mr-2" />
                  Enregistrer
              </button>
          </form>
      </div>
  );

  return (
    <div className="space-y-6">
      {renderModal()}

      <div className="flex space-x-1 bg-white p-1 rounded-xl shadow-sm max-w-xl mx-auto overflow-x-auto animate-fade-in">
        <button 
          onClick={() => setActiveTab('marketplace')}
          className={`flex-1 whitespace-nowrap py-2 px-2 text-xs md:text-sm font-medium rounded-lg transition-all relative ${activeTab === 'marketplace' ? 'bg-blue-100 text-blue-700 shadow-sm' : 'text-gray-500 hover:bg-gray-50'}`}
        >
