          {availableMissions.length > 0 && (
            <span className="absolute -top-1 -right-1 bg-red-500 text-white text-[10px] font-bold w-5 h-5 flex items-center justify-center rounded-full border-2 border-white animate-bounce">
                {availableMissions.length}
            </span>
          )}
        </button>
        <button 
          onClick={() => setActiveTab('my-missions')}
          className={`flex-1 whitespace-nowrap py-2 px-2 text-xs md:text-sm font-medium rounded-lg transition-all ${activeTab === 'my-missions' ? 'bg-blue-100 text-blue-700 shadow-sm' : 'text-gray-500 hover:bg-gray-50'}`}
        >
          En cours
        </button>
        <button 
          onClick={() => setActiveTab('wallet')}
          className={`flex-1 whitespace-nowrap py-2 px-2 text-xs md:text-sm font-medium rounded-lg transition-all ${activeTab === 'wallet' ? 'bg-blue-100 text-blue-700 shadow-sm' : 'text-gray-500 hover:bg-gray-50'}`}
        >
          Portefeuille
        </button>
        <button 
          onClick={() => setActiveTab('profile')}
          className={`flex-1 whitespace-nowrap py-2 px-2 text-xs md:text-sm font-medium rounded-lg transition-all ${activeTab === 'profile' ? 'bg-blue-100 text-blue-700 shadow-sm' : 'text-gray-500 hover:bg-gray-50'}`}
        >
          Mon Profil
        </button>
      </div>

      <div className="animate-fade-in">
        {activeTab === 'marketplace' && renderMarketplace()}
        {activeTab === 'my-missions' && renderMyMissions()}
        {activeTab === 'wallet' && renderWallet()}
        {activeTab === 'profile' && renderProfile()}
      </div>
    </div>
  );
}
