                                      <div className="flex items-center text-yellow-500 bg-yellow-50 px-3 py-1.5 rounded-lg border border-yellow-100">
                                          <div className="flex mr-2">
                                              {[...Array(5)].map((_, i) => (
                                                  <Star key={i} size={12} fill={i < (mission.clientRating || 0) ? "currentColor" : "none"} className={i < (mission.clientRating || 0) ? "" : "text-gray-300"}/>
                                              ))}
                                          </div>
                                          <span className="text-xs font-bold text-yellow-700">Votre avis</span>
                                      </div>
                                  )
                              )}
                          </div>
                      </div>
                  );
              })
          )}
      </div>
  );

  const renderProfile = () => (
      <div className="bg-white rounded-2xl shadow-sm p-8 max-w-xl mx-auto animate-slide-up">
          <h2 className="text-xl font-bold text-gray-800 mb-6">Mon Profil</h2>
          <form onSubmit={handleProfileSubmit} className="space-y-4">
              <input type="text" value={profileForm.name} onChange={e => setProfileForm({...profileForm, name: e.target.value})} className="w-full p-3 border rounded-lg" placeholder="Nom" />
              <input type="text" value={profileForm.phone} onChange={e => setProfileForm({...profileForm, phone: e.target.value})} className="w-full p-3 border rounded-lg" placeholder="Téléphone" />
              <div className="relative">
                  <select value={profileForm.city} onChange={e => setProfileForm({...profileForm, city: e.target.value})} className="w-full p-3 border rounded-lg appearance-none">
                       {CITIES.map(c => <option key={c} value={c}>{c}</option>)}
