              </div>
              <input type="text" value={profileForm.address} onChange={e => setProfileForm({...profileForm, address: e.target.value})} className="w-full p-3 border rounded-lg" placeholder="Adresse" />
              <button type="submit" className="w-full bg-blue-600 text-white py-3 rounded-xl font-bold flex justify-center items-center"><Save size={18} className="mr-2"/> Enregistrer</button>
          </form>
      </div>
  );

  return (
    <div className="space-y-6">
      {/* RATING MODAL */}
      {renderRatingModal()}

      {showPaymentModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4 backdrop-blur-sm">
          <div className="bg-white rounded-2xl p-6 w-full max-w-md shadow-2xl animate-scale-in">
            <h3 className="text-xl font-bold mb-4 flex items-center"><DollarSign className="mr-2 text-green-600"/> Paiement Sécurisé</h3>
            <div className="bg-gray-50 p-4 rounded-xl mb-6"><div className="flex justify-between font-bold text-xl text-blue-600"><span>Total</span><span>{totalPrice.toLocaleString()} FCFA</span></div></div>
            <div className="flex space-x-3">
              <button onClick={() => setShowPaymentModal(false)} className="flex-1 py-3 text-gray-600">Annuler</button>
              <button onClick={confirmPayment} disabled={isProcessingPayment} className="flex-1 py-3 bg-green-600 text-white rounded-xl font-bold flex justify-center">{isProcessingPayment ? <Loader2 className="animate-spin" /> : "Payer & Valider"}</button>
            </div>
          </div>
        </div>
      )}

      <div className="flex space-x-1 bg-white p-1 rounded-xl shadow-sm max-w-md mx-auto">
        <button onClick={() => setActiveTab('new')} className={`flex-1 py-2 px-4 text-sm font-medium rounded-lg ${activeTab === 'new' ? 'bg-blue-100 text-blue-700' : 'text-gray-500 hover:bg-gray-50'}`}>Commander</button>
        <button onClick={() => setActiveTab('history')} className={`flex-1 py-2 px-4 text-sm font-medium rounded-lg ${activeTab === 'history' ? 'bg-blue-100 text-blue-700' : 'text-gray-500 hover:bg-gray-50'}`}>Mes Missions {myMissions.length > 0 && <span className="ml-1 bg-red-500 text-white text-[10px] px-1.5 rounded-full">{myMissions.length}</span>}</button>
        <button onClick={() => setActiveTab('profile')} className={`flex-1 py-2 px-4 text-sm font-medium rounded-lg ${activeTab === 'profile' ? 'bg-blue-100 text-blue-700' : 'text-gray-500 hover:bg-gray-50'}`}>Profil</button>
      </div>

      <div>
        {activeTab === 'new' && renderNewRequest()}
        {activeTab === 'history' && renderHistory()}
        {activeTab === 'profile' && renderProfile()}
      </div>
    </div>
  );
}
