## src/components/ProviderDashboard.tsx

Optimisation de l'affichage des compétences dans le profil prestataire (grille responsive 2 colonnes sur mobile) pour éviter que le texte ne soit coupé.

```tsx
import React, { useState } from 'react';
import { User, Mission, MissionStatus, ServiceCategory, Transaction } from '../types';
import { SERVICE_ICONS, CITIES } from '../constants';
import { MapPin, Clock, CheckCircle, AlertTriangle, Star, Calendar, Phone, Navigation, User as UserIcon, Save, Wallet, LayoutGrid, DollarSign, ChevronDown, Camera, List, ShoppingBag } from 'lucide-react';

interface ProviderDashboardProps {
  currentUser: User;
  missions: Mission[];
  users: User[];
  transactions: Transaction[];
  onUpdateMissionStatus: (missionId: string, status: MissionStatus, providerId?: string, estimation?: { arrivalTime: string, distance: number }) => void;
  onDisputeMission: (missionId: string, reason: string) => void;
  onRateClient: (missionId: string, rating: number, comment: string) => void;
  onUpdateUser: (data: Partial<User>) => void;
  onRequestWithdrawal: (amount: number, method: string) => void;
}

export default function ProviderDashboard({ currentUser, missions, users, transactions, onUpdateMissionStatus, onDisputeMission, onRateClient, onUpdateUser, onRequestWithdrawal }: ProviderDashboardProps) {
  const [activeTab, setActiveTab] = useState<'marketplace' | 'my-missions' | 'wallet' | 'profile'>('marketplace');

  // Profile State
  const [profileForm, setProfileForm] = useState({
    name: currentUser.name,
    phone: currentUser.phone,
    address: currentUser.address || '',
    city: currentUser.city || 'Abidjan',
    password: currentUser.password || ''
  });
  const [selectedServices, setSelectedServices] = useState<ServiceCategory[]>(currentUser.services || []);
  const [newAvatar, setNewAvatar] = useState<string | null>(null);

  // Wallet State
  const [withdrawalAmount, setWithdrawalAmount] = useState<number>(0);

  // Data Filtering
  const myMissions = missions.filter(m => m.providerId === currentUser.id);
  const activeMyMissionsCount = myMissions.filter(m => [MissionStatus.ACCEPTED, MissionStatus.IN_PROGRESS].includes(m.status)).length;

  const availableMissions = missions.filter(m => m.status === MissionStatus.PENDING && !m.providerId && (!currentUser.city || m.city === currentUser.city) && (!currentUser.services || currentUser.services.includes(m.category)));

  const totalEarnings = myMissions.filter(m => m.status === MissionStatus.COMPLETED).reduce((sum, m) => sum + m.providerAmount, 0);
  const withdrawn = transactions.filter(t => t.type === 'PAYOUT' && t.userId === currentUser.id).reduce((sum, t) => sum + t.amount, 0);
  const balance = Math.max(0, totalEarnings - withdrawn);

  // Modal State
  const [selectedMissionId, setSelectedMissionId] = useState<string | null>(null);
  const [modalType, setModalType] = useState<'DISPUTE' | 'RATING' | null>(null);
  const [inputText, setInputText] = useState('');
  const [ratingValue, setRatingValue] = useState(5);

  const openRating = (id: string) => {
    setSelectedMissionId(id);
    setModalType('RATING');
    setInputText('');
    setRatingValue(5);
  };

  const submitModal = () => {
    if (!selectedMissionId) return;
    if (modalType === 'RATING') {
      onRateClient(selectedMissionId, ratingValue, inputText);
    }
    setModalType(null);
    setSelectedMissionId(null);
  };

  const handleAcceptMission = (missionId: string) => {
      // Simulate GPS Calculation
      const arrival = new Date(); arrival.setMinutes(arrival.getMinutes() + 30);
      onUpdateMissionStatus(missionId, MissionStatus.ACCEPTED, currentUser.id, { arrivalTime: arrival.toISOString(), distance: 5 });
      setActiveTab('my-missions');
  };

  const handleProfileSubmit = (e: React.FormEvent) => {
      e.preventDefault();
      onUpdateUser({
          ...profileForm,
          services: selectedServices,
          avatarUrl: newAvatar || currentUser.avatarUrl
      });
      alert("✅ Profil mis à jour avec succès !");
  };

  const toggleService = (service: ServiceCategory) => {
      if (selectedServices.includes(service)) {
          setSelectedServices(selectedServices.filter(s => s !== service));
      } else {
          setSelectedServices([...selectedServices, service]);
      }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) {
          const reader = new FileReader();
          reader.onloadend = () => setNewAvatar(reader.result as string);
          reader.readAsDataURL(file);
      }
  };

  const renderModal = () => {
    if (!modalType) return null;
    return (
      <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4 backdrop-blur-sm">
        <div className="bg-white rounded-2xl p-6 w-full max-w-md animate-scale-in shadow-2xl">
          <h3 className="text-xl font-bold mb-4 text-blue-600">Noter le client</h3>
          <div className="flex justify-center space-x-2 mb-4">
              {[1, 2, 3, 4, 5].map((star) => (
