### Étape 2 : Corriger le Dashboard (`ClientDashboard.tsx`)
Je vais changer la structure pour utiliser `export default function` au début. Cela supprime l'erreur de la ligne 472 à la fin du fichier et rend le code plus robuste.

**Copiez ce code et remplacez TOUT le contenu de `src/components/ClientDashboard.tsx` :**

```tsx
import React, { useState, useEffect } from 'react';
import { User, Mission, MissionStatus, ServiceCategory, MarketItem } from '../types';
import { SERVICE_ICONS, CITIES, BASE_RATES, MARKET_PACKAGING_FEE, MARKET_SERVICE_FEE, MARKET_DELIVERY_FEE, LAUNDRY_MIN_PRICE, LAUNDRY_EXTRA_PRICE, LAUNDRY_MIN_QTY } from '../constants';
import { MapPin, Calendar, Clock, Send, Loader2, Star, AlertTriangle, CheckCircle, Crosshair, Plus, Trash2, ShoppingBag, DollarSign, User as UserIcon, Save, History, PlusCircle, Map as MapIcon, Menu, Timer, ChevronDown, Shirt, ThumbsUp, ChevronUp, X } from 'lucide-react';

interface ClientDashboardProps {
  currentUser: User;
  missions: Mission[];
  onAddMission: (newMission: Mission, paymentMethod: string) => Promise<void>;
  onValidateMission: (missionId: string) => void;
  onDisputeMission: (missionId: string, reason: string) => void;
  onRateMission: (missionId: string, rating: number, comment: string) => void;
  baseRates: Record<ServiceCategory, number>;
  commissionRate: number;
  onUpdateUser: (data: Partial<User>) => void;
}

// Configuration des styles
const CATEGORY_STYLES: Record<ServiceCategory, { active: string; inactive: string }> = {
  [ServiceCategory.CLEANING]: { active: "bg-sky-600 border-sky-700 text-white shadow-lg scale-105 ring-2 ring-sky-300", inactive: "bg-white border-sky-100 text-sky-700 hover:bg-sky-50" },
  [ServiceCategory.COOKING]: { active: "bg-orange-600 border-orange-700 text-white shadow-lg scale-105 ring-2 ring-orange-300", inactive: "bg-white border-orange-100 text-orange-700 hover:bg-orange-50" },
  [ServiceCategory.ELDERLY_CARE]: { active: "bg-emerald-600 border-emerald-700 text-white shadow-lg scale-105 ring-2 ring-emerald-300", inactive: "bg-white border-emerald-100 text-emerald-700 hover:bg-emerald-50" },
  [ServiceCategory.GARDENING]: { active: "bg-green-600 border-green-700 text-white shadow-lg scale-105 ring-2 ring-green-300", inactive: "bg-white border-green-100 text-green-700 hover:bg-green-50" },
  [ServiceCategory.LAUNDRY]: { active: "bg-indigo-600 border-indigo-700 text-white shadow-lg scale-105 ring-2 ring-indigo-300", inactive: "bg-white border-indigo-100 text-indigo-700 hover:bg-indigo-50" },
  [ServiceCategory.BABYSITTING]: { active: "bg-pink-600 border-pink-700 text-white shadow-lg scale-105 ring-2 ring-pink-300", inactive: "bg-white border-pink-100 text-pink-700 hover:bg-pink-50" },
  [ServiceCategory.MARKET]: { active: "bg-amber-600 border-amber-700 text-white shadow-lg scale-105 ring-2 ring-amber-300", inactive: "bg-white border-amber-100 text-amber-700 hover:bg-amber-50" },
};

// Utilisation de export default function directement pour éviter les erreurs en bas de page
export default function ClientDashboard({
  currentUser,
  missions,
  onAddMission,
  onValidateMission,
  onDisputeMission,
  onRateMission,
  baseRates,
  commissionRate,
  onUpdateUser
}: ClientDashboardProps) {
  const [activeTab, setActiveTab] = useState<'new' | 'history' | 'profile'>('new');

  // --- New Mission State ---
  const [selectedCategory, setSelectedCategory] = useState<ServiceCategory>(ServiceCategory.CLEANING);
  const [description, setDescription] = useState('');
  const [date, setDate] = useState('');
  const [time, setTime] = useState(''); 
  const [endTime, setEndTime] = useState(''); 
  const [duration, setDuration] = useState(2); 

  const [laundryQuantity, setLaundryQuantity] = useState<number>(20); 

  const [location, setLocation] = useState<string>(currentUser.address || '');
  const [debouncedLocation, setDebouncedLocation] = useState<string>(currentUser.address || '');
  const [city, setCity] = useState(currentUser.city || 'Abidjan');
  const [isLocating, setIsLocating] = useState(false);
  const [statusFilter, setStatusFilter] = useState<string>('TOUTES');

  // Market Specifics
  const [marketItems, setMarketItems] = useState<MarketItem[]>([]);
  const [newItemName, setNewItemName] = useState('');
  const [newItemPrice, setNewItemPrice] = useState<string>(''); 
  const [deliveryWindow, setDeliveryWindow] = useState("");

  const [showPaymentModal, setShowPaymentModal] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState('Mobile Money');
  const [isProcessingPayment, setIsProcessingPayment] = useState(false);

  const [expandedMissionId, setExpandedMissionId] = useState<string | null>(null);

  const [showRatingModal, setShowRatingModal] = useState(false);
  const [ratingMissionId, setRatingMissionId] = useState<string | null>(null);
  const [ratingValue, setRatingValue] = useState(5);
  const [ratingComment, setRatingComment] = useState('');

  const [profileForm, setProfileForm] = useState({
      name: currentUser.name,
      phone: currentUser.phone,
      email: currentUser.email,
      address: currentUser.address || '',
      city: currentUser.city || 'Abidjan',
  });

  useEffect(() => {
    const handler = setTimeout(() => setDebouncedLocation(location), 1500);
    return () => clearTimeout(handler);
  }, [location]);

  useEffect(() => {
    if (time && endTime && selectedCategory !== ServiceCategory.MARKET && selectedCategory !== ServiceCategory.LAUNDRY) {
      const [startH, startM] = time.split(':').map(Number);
      const [endH, endM] = endTime.split(':').map(Number);
      let totalHours = (endH - startH) + ((endM - startM) / 60);
      if (totalHours <= 0) totalHours = 1;
      setDuration(Math.round(totalHours * 10) / 10);
    }
  }, [time, endTime, selectedCategory]);

  const getDeliveryOptions = () => {
      const options = [];
      const now = new Date();
      const currentHour = now.getHours();
      if (currentHour < 11) options.push("Aujourd'hui avant 12h");
      if (currentHour < 13) options.push("Aujourd'hui avant 14h");
      if (currentHour < 17) options.push("Aujourd'hui avant 18h");
      options.push("Demain Matin (8h - 12h)");
      options.push("Demain Après-midi (14h - 18h)");
      return options;
  };

  useEffect(() => {
      const opts = getDeliveryOptions();
      if (opts.length > 0 && !deliveryWindow) setDeliveryWindow(opts[0]);
  }, []);

  const getMissionPrice = () => {
      if (selectedCategory === ServiceCategory.MARKET) {
          const itemsTotal = marketItems.reduce((acc, item) => acc + item.price, 0);
          if (itemsTotal === 0) return 0;
          return itemsTotal + MARKET_PACKAGING_FEE + MARKET_SERVICE_FEE + MARKET_DELIVERY_FEE;
      }
      if (selectedCategory === ServiceCategory.LAUNDRY) {
          if (laundryQuantity <= LAUNDRY_MIN_QTY) return LAUNDRY_MIN_PRICE;
          const extraItems = laundryQuantity - LAUNDRY_MIN_QTY;
          return LAUNDRY_MIN_PRICE + (extraItems * LAUNDRY_EXTRA_PRICE);
      }
      const rate = baseRates[selectedCategory] || 2500;
      return Math.round(rate * duration);
  };

  const totalPrice = getMissionPrice();

  const myMissions = missions
    .filter(m => m.clientId === currentUser.id)
    .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())
    .filter(m => {
      if (statusFilter === 'TOUTES') return true;
      if (statusFilter === 'EN_ATTENTE') return m.status === MissionStatus.PENDING;
      if (statusFilter === 'EN_COURS') return [MissionStatus.ACCEPTED, MissionStatus.IN_PROGRESS, MissionStatus.PAYMENT_PENDING].includes(m.status);
      if (statusFilter === 'TERMINEE') return m.status === MissionStatus.COMPLETED;
      if (statusFilter === 'ANNULEE') return [MissionStatus.CANCELLED, MissionStatus.ARCHIVED, MissionStatus.DISPUTED].includes(m.status);
      return true;
  });

  const handleLocateMe = () => {
    if (!navigator.geolocation) { alert("Pas de GPS"); return; }
    setIsLocating(true);
    navigator.geolocation.getCurrentPosition(
        async (position) => {
            const { latitude, longitude } = position.coords;
            const latLng = `${latitude.toFixed(5)}, ${longitude.toFixed(5)}`;
            setLocation(latLng);
            try {
                const response = await fetch(`https://nominatim.openstreetmap.org/reverse?format=json&lat=${latitude}&lon=${longitude}`);
                const data = await response.json();
                if (data && data.address) {
                    const formattedAddr = [data.address.road, data.address.suburb].filter(Boolean).join(', ');
                    if (formattedAddr) setLocation(`${formattedAddr} (${latLng})`);
                    if (data.address.city) setCity(data.address.city);
                }
            } catch (e) {}
            setIsLocating(false);
        },
        () => { alert("Erreur GPS"); setIsLocating(false); },
        { enableHighAccuracy: true }
    );
  };

  const handleAddItem = () => {
      const price = parseFloat(newItemPrice);
      if (!newItemName || isNaN(price) || price <= 0) return;
      setMarketItems([...marketItems, { name: newItemName, price: price }]);
      setNewItemName('');
      setNewItemPrice('');
  };

  const handleRemoveItem = (index: number) => {
      const newItems = [...marketItems];
      newItems.splice(index, 1);
      setMarketItems(newItems);
  };

  const handleInitiateMission = (e: React.FormEvent) => {
      e.preventDefault();
      if (selectedCategory !== ServiceCategory.MARKET) {
          if (!date || !time) { alert("Date/Heure requises"); return; }
          if (selectedCategory !== ServiceCategory.LAUNDRY && !endTime) { alert("Heure de fin requise"); return; }
      }
      if (selectedCategory !== ServiceCategory.MARKET && !description) { alert("Description requise"); return; }
      if (selectedCategory === ServiceCategory.MARKET && marketItems.length === 0) { alert("Ajoutez des articles"); return; }
      setShowPaymentModal(true);
  };

  const confirmPayment = async () => {
      setIsProcessingPayment(true);

      let finalDate = date;
      let finalTime = time;
      if (selectedCategory === ServiceCategory.MARKET) {
          const now = new Date();
          if (!finalDate) finalDate = now.toISOString().split('T')[0];
          if (!finalTime) finalTime = now.toLocaleTimeString('en-US', { hour12: false, hour: "2-digit", minute: "2-digit" });
      }

      const isoDate = `${finalDate}T${finalTime}`;
      const isoEndTime = endTime ? `${finalDate}T${endTime}` : undefined;

      const newMission: Mission = {
          id: `m${Date.now()}`,
          title: selectedCategory === ServiceCategory.MARKET ? 'Course au marché' : `${selectedCategory}`,
          clientId: currentUser.id,
          clientName: currentUser.name,
          category: selectedCategory,
          description: description || (selectedCategory === ServiceCategory.MARKET ? "Liste de courses" : `Lessive de ${laundryQuantity} pièces`),
          location: location || "Non spécifié",
          city: city,
          date: isoDate,
          endTime: isoEndTime,
          durationHours: duration,
          quantity: selectedCategory === ServiceCategory.LAUNDRY ? laundryQuantity : undefined,
          totalPrice: totalPrice,
          commission: totalPrice * commissionRate,
          providerAmount: totalPrice * (1 - commissionRate),
          status: MissionStatus.PENDING,
          createdAt: new Date().toISOString(),
          marketItems: selectedCategory === ServiceCategory.MARKET ? marketItems : undefined,
          deliveryWindow: selectedCategory === ServiceCategory.MARKET ? deliveryWindow : undefined,
      };

      try {
        await onAddMission(newMission, paymentMethod);
        setActiveTab('history');
        setDescription(''); setMarketItems([]); setDate(''); setTime(''); setEndTime(''); setLaundryQuantity(20);
      } catch (error) { console.error(error); } finally {
        setIsProcessingPayment(false);
        setShowPaymentModal(false);
      }
  };

  const handleProfileSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onUpdateUser(profileForm);
    alert("✅ Profil mis à jour !");
    setActiveTab('new');
  };

  const toggleDetails = (missionId: string) => {
      setExpandedMissionId(expandedMissionId === missionId ? null : missionId);
  };

  const openRatingModal = (missionId: string) => {
      setRatingMissionId(missionId);
      setRatingValue(5);
      setRatingComment('');
      setShowRatingModal(true);
  };

  const handleRateSubmit = () => {
      if (ratingMissionId) {
          onRateMission(ratingMissionId, ratingValue, ratingComment);
          setShowRatingModal(false);
          setRatingMissionId(null);
      }
  };

  const renderNewRequest = () => {
    const mapQuery = debouncedLocation ? debouncedLocation : city;
    const mapUrl = `https://maps.google.com/maps?q=${encodeURIComponent(mapQuery)}&t=k&z=${debouncedLocation ? '20' : '17'}&ie=UTF8&iwloc=&output=embed`;
    const today = new Date().toISOString().split('T')[0];

    return (
      <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden animate-slide-up pb-20 md:pb-0">
          <div className="p-6 border-b border-gray-100 bg-gray-50">
              <h2 className="text-xl font-bold text-gray-800 flex items-center">
                  <PlusCircle className="mr-2 text-blue-600"/> Nouvelle Demande
              </h2>
          </div>
          <div className="p-6">
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
                  {Object.values(ServiceCategory).map((cat) => {
                      const Icon = SERVICE_ICONS[cat];
                      const isSelected = selectedCategory === cat;
                      const style = CATEGORY_STYLES[cat];
                      return (
                          <button
                              key={cat}
                              onClick={() => { setSelectedCategory(cat); if (cat === ServiceCategory.LAUNDRY) setLaundryQuantity(20); }}
                              className={`flex flex-col items-center justify-center p-4 rounded-2xl border transition-all ${isSelected ? style.active : style.inactive}`}
                          >
                              <div className={`p-3 rounded-full mb-3 ${isSelected ? 'bg-white/20' : 'bg-gray-100'}`}><Icon size={28} className={isSelected ? 'text-white' : 'text-gray-600'} /></div>
                              <span className="text-xs font-bold text-center">{cat}</span>
                          </button>
                      );
                  })}
              </div>

              <form onSubmit={handleInitiateMission} className="space-y-6">
                  <div className="bg-gray-50 p-4 rounded-xl border border-gray-200">
                        <label className="block text-sm font-bold text-gray-800 mb-3">Lieu</label>
                        <div className="relative flex items-center mb-4">
                            <input type="text" required value={location} onChange={(e) => setLocation(e.target.value)} className="w-full pl-10 p-3 border rounded-lg font-bold" placeholder="Adresse..." />
                            <MapPin size={16} className="absolute left-3 text-gray-400" />
                            <button type="button" onClick={handleLocateMe} disabled={isLocating} className="absolute right-1 px-3 py-2 bg-blue-600 text-white rounded-md text-xs font-bold">{isLocating ? <Loader2 className="animate-spin" size={14}/> : 'GPS'}</button>
                        </div>
                        <iframe width="100%" height="200" frameBorder="0" src={mapUrl} className="rounded-lg shadow-inner"></iframe>
                  </div>

                  {selectedCategory === ServiceCategory.MARKET ? (
                      <div className="bg-orange-50 p-6 rounded-xl border border-orange-100 animate-fade-in shadow-sm">
                          <h3 className="font-bold text-orange-800 mb-4 flex items-center text-lg"><ShoppingBag className="mr-2"/> Ma Liste</h3>
                          <div className="flex gap-2 mb-4">
                              <input type="text" placeholder="Article" className="flex-grow p-3 rounded-lg border" value={newItemName} onChange={(e) => setNewItemName(e.target.value)} />
                              <input type="number" placeholder="Prix" className="w-24 p-3 rounded-lg border" value={newItemPrice} onChange={(e) => setNewItemPrice(e.target.value)} />
                              <button type="button" onClick={handleAddItem} className="bg-orange-600 text-white p-3 rounded-lg"><Plus size={20} /></button>
                          </div>
                          {marketItems.map((item, idx) => (
                              <div key={idx} className="flex justify-between items-center py-2 border-b border-orange-100 text-sm">
                                  <span>{item.name}</span>
                                  <div className="flex items-center"><span className="font-bold mr-3">{item.price} F</span><button type="button" onClick={() => handleRemoveItem(idx)}><Trash2 size={14} className="text-red-400" /></button></div>
                              </div>
                          ))}
                          <div className="mt-4 pt-3 border-t border-orange-200 text-sm text-gray-600 bg-white p-3 rounded-lg">
                              <p className="flex justify-between"><span>Articles:</span> <span>{marketItems.reduce((a,b)=>a+b.price,0)} F</span></p>
                              <p className="flex justify-between"><span>Sachet:</span> <span>{MARKET_PACKAGING_FEE} F</span></p>
                              <p className="flex justify-between"><span>Course:</span> <span>{MARKET_SERVICE_FEE} F</span></p>
                              <p className="flex justify-between font-bold"><span>Livraison:</span> <span>{MARKET_DELIVERY_FEE} F</span></p>
                          </div>
                          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-4">
                              <input type="date" min={today} value={date} onChange={(e) => setDate(e.target.value)} onClick={(e) => e.currentTarget.showPicker()} className="p-3 bg-gray-900 text-white rounded-xl font-bold cursor-pointer" style={{colorScheme:'dark'}}/>
                              <select value={deliveryWindow} onChange={(e) => setDeliveryWindow(e.target.value)} className="p-3 bg-white border border-gray-300 rounded-xl font-bold text-gray-900 appearance-none">{getDeliveryOptions().map(opt => <option key={opt} value={opt}>{opt}</option>)}</select>
                          </div>
                      </div>
                  ) : selectedCategory === ServiceCategory.LAUNDRY ? (
                      <div className="space-y-6 animate-fade-in">
                          <textarea required value={description} onChange={(e) => setDescription(e.target.value)} className="w-full p-4 border-2 border-gray-200 rounded-2xl" placeholder="Instructions..." />
                          <div className="bg-indigo-50 p-6 rounded-xl border border-indigo-100">
                              <label className="block text-indigo-900 font-bold mb-2">Nombre de pièces (Min. 20)</label>
                              <input type="number" min="20" value={laundryQuantity} onChange={(e) => setLaundryQuantity(Math.max(20, parseInt(e.target.value) || 20))} className="w-full p-4 text-2xl font-bold text-indigo-900 bg-white border-2 border-indigo-200 rounded-xl text-center" />
                              <div className="grid grid-cols-2 gap-4 mt-4">
                                  <input type="date" min={today} value={date} onChange={(e) => setDate(e.target.value)} onClick={(e) => e.currentTarget.showPicker()} className="p-3 bg-gray-900 text-white rounded-xl font-bold cursor-pointer" style={{colorScheme:'dark'}}/>
                                  <input type="time" value={time} onChange={(e) => setTime(e.target.value)} onClick={(e) => e.currentTarget.showPicker()} className="p-3 bg-gray-900 text-white rounded-xl font-bold cursor-pointer" style={{colorScheme:'dark'}}/>
                              </div>
                          </div>
                      </div>
                  ) : (
                      <div className="space-y-6 animate-fade-in">
                          <textarea required value={description} onChange={(e) => setDescription(e.target.value)} className="w-full p-4 border rounded-xl" placeholder="Description..." />
                          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                              <input type="date" required min={today} value={date} onChange={(e) => setDate(e.target.value)} onClick={(e) => e.currentTarget.showPicker()} className="p-4 bg-gray-900 text-white rounded-xl font-bold cursor-pointer" style={{colorScheme:'dark'}}/>
                              <input type="time" required value={time} onChange={(e) => setTime(e.target.value)} onClick={(e) => e.currentTarget.showPicker()} className="p-4 bg-gray-900 text-white rounded-xl font-bold cursor-pointer" style={{colorScheme:'dark'}}/>
                              <input type="time" required value={endTime} onChange={(e) => setEndTime(e.target.value)} onClick={(e) => e.currentTarget.showPicker()} className="p-4 bg-gray-900 text-white rounded-xl font-bold cursor-pointer" style={{colorScheme:'dark'}}/>
                          </div>
                      </div>
                  )}

                  <div className="flex items-center justify-between pt-6 border-t border-gray-100">
                      <div><p className="text-gray-500 text-xs uppercase font-bold">Total</p><p className="text-3xl font-extrabold text-blue-900">{totalPrice.toLocaleString()} F</p></div>
                      <button type="submit" className="bg-blue-600 text-white px-8 py-4 rounded-xl font-bold flex items-center shadow-lg"><Send size={20} className="mr-2" /> Commander</button>
                  </div>
              </form>
          </div>
      </div>
    );
  };

  const renderHistory = () => (
      <div className="space-y-4 animate-slide-up relative h-full min-h-[50vh]">
          <div className="flex space-x-2 overflow-x-auto pb-2 scrollbar-hide sticky top-0 bg-gray-50 z-10 py-2">
              {['TOUTES', 'EN_ATTENTE', 'EN_COURS', 'TERMINEE'].map(status => (
                  <button key={status} onClick={() => setStatusFilter(status)} className={`px-4 py-2 rounded-full text-xs font-bold whitespace-nowrap ${statusFilter === status ? 'bg-gray-800 text-white' : 'bg-white border'}`}>{status.replace('_', ' ')}</button>
              ))}
          </div>

          {myMissions.length === 0 ? (
              <div className="text-center py-12 bg-white rounded-2xl border border-dashed"><History size={48} className="mx-auto text-gray-300 mb-3" /><p className="text-gray-500">Aucune mission.</p></div>
          ) : (
              myMissions.map(mission => {
                  const Icon = SERVICE_ICONS[mission.category];
                  const isValidated = mission.status === MissionStatus.ACCEPTED || mission.status === MissionStatus.IN_PROGRESS;
                  const isExpanded = expandedMissionId === mission.id;

                  return (
                      <div key={mission.id} className={`bg-white p-6 rounded-2xl shadow-sm border ${isValidated ? 'border-green-200' : 'border-gray-100'}`}>
                          {isValidated && <div className="bg-green-50 border border-green-100 text-green-800 p-3 rounded-xl mb-4 flex items-center"><ThumbsUp size={20} className="mr-3" /><div><p className="font-bold text-sm">Commande Validée !</p><p className="text-xs">Par: {mission.providerName}</p></div></div>}
                          <div className="flex justify-between items-start mb-4">
                              <div className="flex items-center space-x-3">
                                  <div className="p-3 bg-gray-50 rounded-xl"><Icon size={24} className="text-gray-600"/></div>
                                  <div>
                                      <h3 className="font-bold text-gray-900">{mission.title}</h3>
                                      <p className="text-xs text-gray-500">{new Date(mission.date).toLocaleDateString()}</p>
                                  </div>
                              </div>
                              <span className="text-xs font-bold bg-blue-100 text-blue-700 px-2 py-1 rounded-full">{mission.status}</span>
                          </div>

                          <button onClick={() => toggleDetails(mission.id)} className="w-full text-left bg-gray-50 p-3 rounded-lg text-xs font-bold flex justify-between mb-4"><span>{isExpanded ? "Masquer" : "Voir détails"}</span>{isExpanded ? <ChevronUp size={16}/> : <ChevronDown size={16}/>}</button>

                          {isExpanded && (
