              <button type="submit" className="w-full bg-blue-600 text-white py-3 rounded-xl font-bold flex justify-center items-center"><Save size={18} className="mr-2"/> Enregistrer</button>
          </form>
      </div>
  );

  return (
    <div className="space-y-6">
      {showRatingModal && (
        <div className="fixed inset-0 bg-black bg-opacity-60 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-2xl p-6 w-full max-w-sm">
                <h3 className="text-xl font-bold text-center mb-4">Noter le service</h3>
