                <button onClick={handleRateSubmit} className="w-full bg-yellow-500 text-white py-3 rounded-xl font-bold">Envoyer</button>
                <button onClick={() => setShowRatingModal(false)} className="w-full text-gray-500 mt-2">Annuler</button>
            </div>
        </div>
      )}

      {showPaymentModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4 backdrop-blur-sm">
          <div className="bg-white rounded-2xl p-6 w-full max-w-md shadow-2xl animate-scale-in">
            <h3 className="text-xl font-bold mb-4 flex items-center"><DollarSign className="mr-2 text-green-600"/> Paiement Sécurisé</h3>
