## src/services/smsService.ts

Désactivation du mode simulation. Les SMS seront désormais gérés par le backend ou Firebase Auth directement.

```typescript
import { sendSmsFunction } from "./firebase";

// PASSAGE EN MODE RÉEL : FALSE
const USE_SIMULATION_MODE = false; 

export const sendVerificationCode = async (phoneNumber: string, code: string): Promise<boolean> => {
  if (USE_SIMULATION_MODE) {
    return new Promise((resolve) => setTimeout(() => resolve(true), 500));
  } else {
    try {
      // En mode réel, on utilise soit Firebase Auth (côté client), 
      // soit cette fonction si vous avez configuré un backend Twilio/Orange.
      // Note: Pour l'inscription actuelle, c'est Auth.tsx qui gère l'envoi via le SDK Client Firebase.
      const response = await sendSmsFunction({ 
        phoneNumber: phoneNumber,
        message: `Votre code Servi+ est : ${code}`,
        provider: 'TWILIO'
      });
      const data = response.data as any;
      return data.success;
    } catch (error) {
      console.error("Erreur SMS Service:", error);
      return false;
    }
  }
};
