const BACKGROUND_IMAGE = "https://images.unsplash.com/photo-1581578731117-104f2a41272c?q=80&w=2070&auto=format&fit=crop";

interface AuthProps {
  users: User[];
  onLogin: (user: User) => void;
  onRegister: (newUser: User) => void;
}

export default function Auth({ users, onLogin, onRegister }: AuthProps) {
  const [viewMode, setViewMode] = useState<'LOGIN' | 'REGISTER' | 'FORGOT_PASSWORD'>('LOGIN');

  // 2FA State (COMMENTÉ POUR LE MOMENT)
  // const [authStep, setAuthStep] = useState<'FORM' | 'VERIFICATION'>('FORM');
  // const [verificationCode, setVerificationCode] = useState(['', '', '', '']);
  // const [confirmationResult, setConfirmationResult] = useState<any>(null);

  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [successMsg, setSuccessMsg] = useState('');
  const [loading, setLoading] = useState(false);
  const [highlightTermsError, setHighlightTermsError] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    city: 'Abidjan',
    password: '',
    confirmPassword: '',
    role: UserRole.CLIENT,
    address: '',
    idNumber: '',
    acceptTerms: false
  });

  const [selectedServices, setSelectedServices] = useState<ServiceCategory[]>([]);
  const [avatarPreview, setAvatarPreview] = useState<string | null>(null);
  const [avatarFile, setAvatarFile] = useState<File | null>(null);
  const [idCardRectoFile, setIdCardRectoFile] = useState<File | null>(null);
  const [idCardVersoFile, setIdCardVersoFile] = useState<File | null>(null);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const value = e.target.type === 'checkbox' ? (e.target as HTMLInputElement).checked : e.target.value;
    setFormData({ ...formData, [e.target.name]: value });
    setError('');
    if (e.target.name === 'acceptTerms') setHighlightTermsError(false);
  };

  const handleRoleSwitch = (newRole: UserRole) => {
      setFormData({
          name: '',
          email: '',
          phone: '',
          city: 'Abidjan',
          password: '',
          confirmPassword: '',
          role: newRole,
          address: '',
          idNumber: '',
          acceptTerms: false
      });
      setSelectedServices([]);
      setAvatarFile(null);
      setAvatarPreview(null);
      setIdCardRectoFile(null);
      setIdCardVersoFile(null);
      setError('');
  };

  const toggleService = (service: ServiceCategory) => {
    if (selectedServices.includes(service)) {
      setSelectedServices(selectedServices.filter(s => s !== service));
    } else {
      setSelectedServices([...selectedServices, service]);
    }
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>, type: 'AVATAR' | 'ID_RECTO' | 'ID_VERSO') => {
    const file = e.target.files?.[0];
    if (file) {
      if (type === 'AVATAR') {
          setAvatarFile(file);
          const reader = new FileReader();
          reader.onloadend = () => setAvatarPreview(reader.result as string);
          reader.readAsDataURL(file);
      } else if (type === 'ID_RECTO') {
          setIdCardRectoFile(file);
      } else if (type === 'ID_VERSO') {
          setIdCardVersoFile(file);
      }
    }
  };

  // --- BYPASS DE LA 2FA (SIMPLIFICATION) ---
  const handleDirectAuth = async (e: React.FormEvent) => {
      e.preventDefault();
      setError('');
      setSuccessMsg('');
      setLoading(true);

      try {
          if (viewMode === 'REGISTER') {
             // Validations Inscription
             if (!formData.acceptTerms) {
                setHighlightTermsError(true); setLoading(false); return;
             }
             if (!avatarFile) throw new Error("Veuillez ajouter une photo de profil.");
             if (formData.password !== formData.confirmPassword) throw new Error("Les mots de passe ne correspondent pas.");
             if (formData.role === UserRole.PROVIDER && selectedServices.length === 0) throw new Error("Veuillez sélectionner au moins une compétence.");
             if (!formData.idNumber) throw new Error("Le numéro de pièce d'identité est obligatoire.");

             // Vérification doublon local (en attendant la DB)
             const userExists = users.some(u => u.phone === formData.phone);
             if(userExists) throw new Error("Ce numéro de téléphone est déjà utilisé.");

             // Création directe (Pas de SMS)
             const avatarUrl = avatarFile ? await uploadImage(avatarFile, `avatars/${Date.now()}_${formData.phone}`) : '';
             const rectoUrl = idCardRectoFile ? await uploadImage(idCardRectoFile, `id_cards/${Date.now()}_recto`) : '';
             const versoUrl = idCardVersoFile ? await uploadImage(idCardVersoFile, `id_cards/${Date.now()}_verso`) : '';

             const newUser: User = {
                  id: `u${Date.now()}`,
                  name: formData.name,
                  email: formData.email || `${formData.phone}@serviplus.ci`,
                  phone: formData.phone,
                  password: formData.password,
                  role: formData.role,
                  address: formData.address,
                  city: formData.city,
                  avatarUrl: avatarUrl || `https://ui-avatars.com/api/?name=${formData.name}`,
                  services: formData.role === UserRole.PROVIDER ? selectedServices : undefined,
                  verified: false,
                  walletBalance: 0,
                  createdAt: new Date().toISOString(),
                  idNumber: formData.idNumber,
                  idCardRecto: rectoUrl,
                  idCardVerso: versoUrl,
                  acceptTerms: true
              };

              onRegister(newUser); // Enregistrement direct dans Firebase via App.tsx

          } else {
              // Validations Connexion
              // On vérifie le numéro ET le mot de passe
              const user = users.find(u => u.phone === formData.phone && u.password === formData.password);

              if (user) {
                  onLogin(user);
              } else {
                  // Check si le numéro existe mais mauvais mot de passe
                  const userExists = users.some(u => u.phone === formData.phone);
                  if (userExists) throw new Error("Mot de passe incorrect.");
                  else throw new Error("Compte introuvable. Veuillez vous inscrire.");
              }
          }

      } catch (err: any) {
          console.error("Auth Error:", err);
          setError(err.message);
          setLoading(false);
      }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50 p-4 font-sans relative overflow-hidden">
        {/* Background Image & Overlay */}
        <div className="absolute inset-0 z-0">
             <img src={BACKGROUND_IMAGE} alt="Background" className="w-full h-full object-cover" />
             <div className="absolute inset-0 bg-blue-900/80 backdrop-blur-sm"></div>
        </div>

        <div className="bg-white rounded-3xl shadow-2xl w-full max-w-lg relative z-10 overflow-hidden animate-scale-in flex flex-col max-h-[90vh]">

            {/* Header / Logo Area */}
            <div className="pt-8 pb-6 px-8 text-center bg-white relative">
                 <div className="w-20 h-20 bg-gradient-to-br from-blue-600 to-blue-800 rounded-2xl flex items-center justify-center text-white font-bold text-3xl shadow-blue-200 shadow-xl mx-auto mb-4 animate-float">
                   S<span className="text-orange-400">+</span>
                 </div>
                 <h1 className="text-3xl font-extrabold text-blue-900 tracking-tight">
                   Servi<span className="text-orange-500">+</span>
                 </h1>
                 <p className="text-gray-500 font-medium mt-1 animate-fade-in delay-200">Votre service à domicile le plus efficace</p>
            </div>

            {/* Scrollable Form Area */}
            <div className="px-8 pb-8 overflow-y-auto custom-scrollbar flex-1">

                {/* Tabs */}
                <div className="flex bg-gray-100 p-1 rounded-xl mb-6">
                    <button
                        onClick={() => { setViewMode('LOGIN'); setError(''); }}
                        className={`flex-1 py-3 text-sm font-bold rounded-lg transition-all ${viewMode === 'LOGIN' ? 'bg-white text-blue-900 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                    >
                        Connexion
                    </button>
                    <button
                        onClick={() => { setViewMode('REGISTER'); setError(''); }}
                        className={`flex-1 py-3 text-sm font-bold rounded-lg transition-all ${viewMode === 'REGISTER' ? 'bg-white text-blue-900 shadow-sm' : 'text-gray-500 hover:text-gray-700'}`}
                    >
                        Inscription
                    </button>
                </div>

                {error && (
                    <div className="bg-red-50 border-l-4 border-red-500 text-red-700 p-4 rounded-r-lg mb-6 text-sm font-medium animate-shake flex items-start">
                        <AlertCircle size={18} className="mr-2 mt-0.5 flex-shrink-0" />
                        <span>{error}</span>
                    </div>
                )}

                {/* FORMULAIRE DIRECT (SANS 2FA) */}
                <form onSubmit={handleDirectAuth} className="space-y-5" key={formData.role}>

                    {/* Role Selection (Register Only) */}
                    {viewMode === 'REGISTER' && (
                        <div className="grid grid-cols-2 gap-4 mb-6">
                            <button
                                type="button"
                                onClick={() => handleRoleSwitch(UserRole.CLIENT)}
                                className={`p-4 rounded-xl border-2 flex flex-col items-center justify-center transition-all ${formData.role === UserRole.CLIENT ? 'border-blue-500 bg-blue-50 text-blue-700' : 'border-gray-200 text-gray-500 hover:border-blue-200'}`}
                            >
                                <UserIcon size={24} className="mb-2" />
                                <span className="font-bold">Je suis Client</span>
                            </button>
                            <button
                                type="button"
                                onClick={() => handleRoleSwitch(UserRole.PROVIDER)}
                                className={`p-4 rounded-xl border-2 flex flex-col items-center justify-center transition-all ${formData.role === UserRole.PROVIDER ? 'border-orange-500 bg-orange-50 text-orange-700' : 'border-gray-200 text-gray-500 hover:border-orange-200'}`}
                            >
                                <Briefcase size={24} className="mb-2" />
                                <span className="font-bold">Je suis Prestataire</span>
                            </button>
                        </div>
                    )}

                    {/* Common Fields */}
                    {viewMode === 'REGISTER' && (
                        <div className="animate-slide-up">
                            {/* PHOTO DE PROFIL OBLIGATOIRE */}
                            <div className="flex justify-center mb-6">
                                <div className="relative group cursor-pointer w-24 h-24">
                                    <div className={`w-full h-full rounded-full overflow-hidden border-4 ${avatarPreview ? 'border-blue-500' : 'border-gray-200'} bg-gray-100 flex items-center justify-center relative transition-colors`}>
                                        {avatarPreview ? (
                                            <img src={avatarPreview} alt="Avatar" className="w-full h-full object-cover" />
                                        ) : (
                                            <Camera size={32} className="text-gray-400" />
                                        )}
                                    </div>
                                    {/* INPUT SÉPARÉ POUR ÉVITER CONFLIT */}
                                    <input type="file" accept="image/*" onChange={(e) => handleFileChange(e, 'AVATAR')} className="absolute inset-0 opacity-0 cursor-pointer w-full h-full z-10" />
                                </div>
                                <p className="text-xs text-center text-gray-500 mt-2">Photo requise *</p>
                            </div>

                            <div className="mb-4">
                                <label className="block text-xs font-bold text-gray-700 mb-1 ml-1">Nom Complet</label>
                                <div className="relative">
                                    <UserIcon className="absolute left-3 top-3.5 text-gray-400" size={18} />
                                    <input
                                        type="text"
                                        name="name"
                                        placeholder="Votre nom et prénoms"
                                        value={formData.name}
                                        onChange={handleChange}
                                        className="w-full pl-10 pr-4 py-3 bg-gray-100 border border-gray-300 rounded-xl focus:ring-2 focus:ring-blue-500 focus:bg-white transition-colors font-bold text-gray-900 placeholder-gray-500"
                                        required
                                    />
                                </div>
                            </div>
                        </div>
                    )}

                    <div>
                        <label className="block text-xs font-bold text-gray-700 mb-1 ml-1">Numéro de téléphone</label>
                        <div className="relative">
                            <Phone className="absolute left-3 top-3.5 text-gray-400" size={18} />
                            <input
                                type="tel"
                                name="phone"
                                placeholder="0707070707"
                                value={formData.phone}
                                onChange={handleChange}
                                className="w-full pl-10 pr-4 py-3 bg-gray-100 border border-gray-300 rounded-xl focus:ring-2 focus:ring-blue-500 focus:bg-white transition-colors font-bold text-gray-900 placeholder-gray-500"
                                required
                            />
                        </div>
                    </div>

                    {viewMode === 'REGISTER' && (
                        <div className="grid grid-cols-2 gap-4 animate-slide-up">
                            <div className="relative">
                                <label className="block text-xs font-bold text-gray-700 mb-1 ml-1">Ville</label>
                                <div className="relative">
                                    <MapPin className="absolute left-3 top-3.5 text-gray-400 z-10" size={18} />
                                    <select
                                        name="city"
                                        value={formData.city}
                                        onChange={handleChange}
                                        className="w-full pl-10 pr-8 py-3 bg-gray-100 border border-gray-300 rounded-xl focus:ring-2 focus:ring-blue-500 focus:bg-white font-bold text-gray-900 appearance-none relative z-0"
                                    >
                                        {CITIES.map(city => <option key={city} value={city}>{city}</option>)}
                                    </select>
                                    <ChevronDown className="absolute right-3 top-3.5 text-gray-500 z-10 pointer-events-none" size={18} />
                                </div>
                            </div>
                            <div>
                                <label className="block text-xs font-bold text-gray-700 mb-1 ml-1">Quartier</label>
                                <input
                                    type="text"
                                    name="address"
                                    placeholder="Ex: Riviera 2"
                                    value={formData.address}
                                    onChange={handleChange}
                                    className="w-full px-4 py-3 bg-gray-100 border border-gray-300 rounded-xl focus:ring-2 focus:ring-blue-500 focus:bg-white font-bold text-gray-900 placeholder-gray-500"
                                />
                            </div>
                        </div>
                    )}

                    {viewMode === 'REGISTER' && formData.role === UserRole.PROVIDER && (
                         <div className="animate-slide-up bg-orange-50 p-4 rounded-xl border border-orange-100">
                            <label className="block text-xs font-bold text-orange-800 mb-3 flex items-center">
                                <LayoutGrid size={16} className="mr-2"/> Sélectionnez vos compétences
                            </label>
                            <div className="grid grid-cols-2 gap-2">
                                {Object.values(ServiceCategory)
                                  .filter(cat => cat !== ServiceCategory.MARKET) 
                                  .map((cat) => (
                                    <button
                                        key={cat}
                                        type="button"
                                        onClick={() => toggleService(cat)}
                                        className={`p-2 rounded-lg text-xs font-bold border transition-all ${
                                            selectedServices.includes(cat)
                                            ? 'bg-orange-500 text-white border-orange-600 shadow-sm' 
                                            : 'bg-white text-gray-600 border-gray-200 hover:bg-gray-50'
                                        }`}
                                    >
                                        {cat}
                                    </button>
                                ))}
                            </div>
                        </div>
                    )}

                    {/* ID Card Verification - FOR ALL USERS */}
                    {viewMode === 'REGISTER' && (
                        <div className="bg-gray-50 p-4 rounded-xl border border-gray-200 animate-slide-up">
                            <div className="flex items-center mb-3">
                                <ShieldCheck className="text-blue-600 mr-2" size={20}/>
                                <h3 className="text-sm font-bold text-gray-800">Vérification d'identité (Obligatoire)</h3>
                            </div>

                            {/* CHAMP SÉPARÉ POUR LE NUMÉRO */}
                            <div className="mb-4">
                                <label className="block text-xs text-gray-500 font-bold mb-1 ml-1">Numéro de la pièce</label>
                                <input
                                    type="text"
                                    name="idNumber"
                                    placeholder="Numéro CNI / Passeport"
                                    value={formData.idNumber}
                                    onChange={handleChange}
                                    className="w-full p-3 border border-gray-300 rounded-lg text-sm font-bold text-gray-900 bg-white focus:ring-2 focus:ring-blue-500 z-20 relative"
                                    required
                                />
                            </div>

                            <div className="grid grid-cols-2 gap-3">
                                <div className={`relative border-2 border-dashed rounded-xl p-4 flex flex-col items-center justify-center cursor-pointer transition-colors h-24 ${idCardRectoFile ? 'border-green-500 bg-green-50' : 'border-gray-300 hover:border-blue-400 bg-white'}`}>
                                    {idCardRectoFile ? <CheckCircle className="text-green-500 mb-1" size={24}/> : <Camera className="text-gray-400 mb-1" size={24}/>}
                                    <span className="text-xs font-bold text-gray-600">Recto</span>
                                    <input type="file" accept="image/png, image/jpeg, application/pdf" onChange={(e) => handleFileChange(e, 'ID_RECTO')} className="absolute opacity-0 w-full h-full cursor-pointer z-10" id="recto-upload" />
                                </div>
                                <div className={`relative border-2 border-dashed rounded-xl p-4 flex flex-col items-center justify-center cursor-pointer transition-colors h-24 ${idCardVersoFile ? 'border-green-500 bg-green-50' : 'border-gray-300 hover:border-blue-400 bg-white'}`}>
                                    {idCardVersoFile ? <CheckCircle className="text-green-500 mb-1" size={24}/> : <Camera className="text-gray-400 mb-1" size={24}/>}
                                    <span className="text-xs font-bold text-gray-600">Verso</span>
                                    <input type="file" accept="image/png, image/jpeg, application/pdf" onChange={(e) => handleFileChange(e, 'ID_VERSO')} className="absolute opacity-0 w-full h-full cursor-pointer z-10" id="verso-upload" />
                                </div>
                            </div>
                        </div>
                    )}

                    {/* Passwords */}
                    <div className="animate-slide-up">
                        <label className="block text-xs font-bold text-gray-700 mb-1 ml-1">Mot de passe</label>
                        <div className="relative">
                            <Lock className="absolute left-3 top-3.5 text-gray-400" size={18} />
                            <input
                                type={showPassword ? "text" : "password"}
                                name="password"
                                placeholder="••••••••"
                                value={formData.password}
                                onChange={handleChange}
                                className="w-full pl-10 pr-10 py-3 bg-gray-100 border border-gray-300 rounded-xl focus:ring-2 focus:ring-blue-500 focus:bg-white transition-colors font-bold text-gray-900 placeholder-gray-500"
                                required
                            />
                            <button
                                type="button"
                                onClick={() => setShowPassword(!showPassword)}
                                className="absolute right-3 top-3.5 text-gray-500 hover:text-blue-600"
                            >
                                {showPassword ? <EyeOff size={18} /> : <Eye size={18} />}
                            </button>
                        </div>
                    </div>

                    {viewMode === 'REGISTER' && (
                        <div className="animate-slide-up">
                             <label className="block text-xs font-bold text-gray-700 mb-1 ml-1">Confirmer Mot de passe</label>
                             <div className="relative">
                                <Lock className="absolute left-3 top-3.5 text-gray-400" size={18} />
                                <input
                                    type="password"
                                    name="confirmPassword"
                                    placeholder="••••••••"
                                    value={formData.confirmPassword}
                                    onChange={handleChange}
                                    className="w-full pl-10 pr-4 py-3 bg-gray-100 border border-gray-300 rounded-xl focus:ring-2 focus:ring-blue-500 focus:bg-white transition-colors font-bold text-gray-900 placeholder-gray-500"
                                    required
                                />
                             </div>
                        </div>
                    )}

                    {viewMode === 'REGISTER' && (
                        <label className={`flex items-center space-x-3 p-3 rounded-lg border cursor-pointer transition-all animate-slide-up ${highlightTermsError ? 'border-red-500 bg-red-50 animate-pulse' : 'border-gray-200 hover:bg-gray-50'}`}>
                            <div className="relative flex items-center">
                                <input
                                    type="checkbox"
                                    name="acceptTerms"
                                    checked={formData.acceptTerms}
                                    onChange={handleChange}
                                    className="w-5 h-5 text-blue-600 rounded focus:ring-blue-500 border-gray-300"
                                />
                            </div>
                            <span className={`text-xs font-medium ${highlightTermsError ? 'text-red-600 font-bold' : 'text-gray-600'}`}>
                                J'accepte les <span className="underline">Conditions d'Utilisation</span> de Servi+
                            </span>
                        </label>
                    )}

                    <button
                        type="submit"
                        disabled={loading}
                        className="w-full bg-blue-600 text-white py-4 rounded-xl font-bold text-lg shadow-lg shadow-blue-200 hover:bg-blue-700 transition-all flex justify-center items-center transform hover:scale-[1.02] active:scale-[0.98]"
                    >
                        {loading ? <Loader2 className="animate-spin" /> : (viewMode === 'LOGIN' ? "Se connecter" : "S'inscrire")}
                    </button>
                </form>

                <div className="mt-6 text-center">
                    {viewMode === 'LOGIN' ? (
                        <>
                            <p className="text-gray-500 text-sm">
                                Pas encore de compte ?{' '}
                                <button onClick={() => setViewMode('REGISTER')} className="text-blue-600 font-bold hover:underline">
                                    Créer un compte
                                </button>
                            </p>
                            <button onClick={() => setViewMode('FORGOT_PASSWORD')} className="mt-2 text-black font-bold text-sm hover:underline">
                                Mot de passe oublié ?
                            </button>
                        </>
                    ) : (
                        <p className="text-gray-500 text-sm">
                            Déjà un compte ?{' '}
                            <button onClick={() => setViewMode('LOGIN')} className="text-blue-600 font-bold hover:underline">
                                Se connecter
                            </button>
                        </p>
                    )}
                </div>
            </div>
        </div>

        {/* Forgot Password Modal */}
        {viewMode === 'FORGOT_PASSWORD' && (
            <div className="absolute inset-0 bg-white z-20 flex flex-col items-center justify-center p-8 animate-slide-up">
                <button 
                  onClick={() => setViewMode('LOGIN')}
                  className="absolute top-8 left-8 p-2 bg-gray-100 rounded-full hover:bg-gray-200 transition-colors"
                >
                    <ChevronLeft size={24} className="text-gray-700" />
                </button>
                <div className="w-full max-w-md text-center">
                    <div className="w-16 h-16 bg-blue-100 rounded-full flex items-center justify-center mx-auto mb-6">
                        <Lock className="text-blue-600" size={32} />
                    </div>
                    <h2 className="text-2xl font-bold text-gray-900 mb-2">Mot de passe oublié</h2>
                    <p className="text-gray-500 mb-8">Entrez votre numéro de téléphone pour recevoir un code de réinitialisation.</p>

                    <div className="relative mb-6 text-left">
                        <Phone className="absolute left-3 top-3.5 text-gray-400" size={18} />
                        <input
                            type="tel"
                            placeholder="0707070707"
                            className="w-full pl-10 pr-4 py-3 bg-gray-100 border border-gray-300 rounded-xl focus:ring-2 focus:ring-blue-500 font-bold text-gray-900"
                        />
                    </div>

                    <button 
                        onClick={() => {
                            alert("Fonctionnalité de réinitialisation simulée. Vérifiez vos SMS.");
                            setViewMode('LOGIN');
                        }}
                        className="w-full bg-blue-600 text-white py-4 rounded-xl font-bold shadow-lg hover:bg-blue-700 transition-all"
                    >
                        Envoyer le code
                    </button>
                </div>
            </div>
        )}
    </div>
  );
};
