import React, { useState, useEffect, useRef } from 'react';
import { UserRole, User, ServiceCategory } from '../types';
import { Eye, EyeOff, Lock, Phone, User as UserIcon, CheckCircle, Camera, AlertCircle, Loader2, MapPin, Briefcase, LayoutGrid, ShieldCheck, ChevronDown, ChevronLeft, Smartphone, Shield } from 'lucide-react';
import { uploadImage, auth, RecaptchaVerifier } from '../services/firebase';
import { 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword,
  multiFactor,
  PhoneAuthProvider,
  PhoneMultiFactorGenerator,
  getMultiFactorResolver
} from "firebase/auth";
import { CITIES } from '../constants';

const BACKGROUND_IMAGE = "https://images.unsplash.com/photo-1581578731117-104f2a41272c?q=80&w=2070&auto=format&fit=crop";

interface AuthProps {
  users: User[];
  onLogin: (user: User) => void;
  onRegister: (newUser: User) => void;
}

export default function Auth({ users, onLogin, onRegister }: AuthProps) {
  const [viewMode, setViewMode] = useState<'LOGIN' | 'REGISTER' | 'FORGOT_PASSWORD'>('LOGIN');
  const [authStep, setAuthStep] = useState<'FORM' | 'MFA_CHALLENGE'>('FORM');
  const [verificationCode, setVerificationCode] = useState(['', '', '', '', '', '']); // MFA uses 6 digits

  // MFA Resolver for Login
  const [mfaResolver, setMfaResolver] = useState<any>(null);
  const [verificationId, setVerificationId] = useState<string>('');

  const recaptchaVerifierRef = useRef<any>(null);

  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [highlightTermsError, setHighlightTermsError] = useState(false);

  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    city: 'Abidjan',
    password: '',
    confirmPassword: '',
    role: UserRole.CLIENT,
    address: '',
    idNumber: '',
    acceptTerms: false
  });

  const [selectedServices, setSelectedServices] = useState<ServiceCategory[]>([]);
  const [avatarPreview, setAvatarPreview] = useState<string | null>(null);
  const [avatarFile, setAvatarFile] = useState<File | null>(null);
  const [idCardRectoFile, setIdCardRectoFile] = useState<File | null>(null);
  const [idCardVersoFile, setIdCardVersoFile] = useState<File | null>(null);

  useEffect(() => {
    return () => {
      if (recaptchaVerifierRef.current) {
        try { recaptchaVerifierRef.current.clear(); } catch (e) {}
      }
    };
  }, []);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const value = e.target.type === 'checkbox' ? (e.target as HTMLInputElement).checked : e.target.value;
    setFormData({ ...formData, [e.target.name]: value });
    setError('');
    if (e.target.name === 'acceptTerms') setHighlightTermsError(false);
  };

  // Fix: Add handleFileChange to process avatar and ID card images
  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>, type: 'AVATAR' | 'ID_RECTO' | 'ID_VERSO') => {
    const file = e.target.files?.[0];
    if (file) {
      if (type === 'AVATAR') {
          setAvatarFile(file);
          const reader = new FileReader();
          reader.onloadend = () => setAvatarPreview(reader.result as string);
          reader.readAsDataURL(file);
      } else if (type === 'ID_RECTO') {
          setIdCardRectoFile(file);
      } else if (type === 'ID_VERSO') {
          setIdCardVersoFile(file);
      }
    }
  };

  const handleCodeChange = (index: number, value: string) => {
      if (value.length > 1) return;
      const newCode = [...verificationCode];
      newCode[index] = value;
      setVerificationCode(newCode);
      if (value && index < 5) document.getElementById(`code-${index + 1}`)?.focus();
  };

  const setupRecaptcha = () => {
    if (recaptchaVerifierRef.current) {
        try { recaptchaVerifierRef.current.clear(); } catch (e) {}
    }
    try {
        const verifier = new RecaptchaVerifier(auth, 'recaptcha-container', {
            'size': 'invisible'
        });
        recaptchaVerifierRef.current = verifier;
        return verifier;
    } catch (e) {
        console.error("Recaptcha Init Error", e);
        return null;
    }
  };

  // --- LOGIQUE MFA IDENTITY PLATFORM ---

  const handleAuthSubmit = async (e: React.FormEvent) => {
      e.preventDefault();
      setError('');
      setLoading(true);

      const email = formData.email || `${formData.phone}@serviplus.ci`;

      try {
          if (viewMode === 'REGISTER') {
              // 1. Validation Inscription
              if (!formData.acceptTerms) { setHighlightTermsError(true); setLoading(false); return; }
              if (!avatarFile || !idCardRectoFile || !idCardVersoFile) throw new Error("Tous les documents et la photo sont requis.");
              if (formData.password !== formData.confirmPassword) throw new Error("Les mots de passe ne correspondent pas.");

              // 2. Création du compte (Identity Platform)
              const userCredential = await createUserWithEmailAndPassword(auth, email, formData.password);
              const user = userCredential.user;

              // 3. Enrôlement MFA (Optionnel mais recommandé pour Identity Platform)
              // Note: Pour une démo simplifiée sans SMS payant immédiat, on peut skip ou simuler
              // Ici on implémente la structure réelle :
              const appVerifier = setupRecaptcha();
              const multiFactorSession = await multiFactor(user).getSession();
              const phoneInfoOptions = {
                  phoneNumber: `+225${formData.phone}`,
                  session: multiFactorSession
              };
              const phoneAuthProvider = new PhoneAuthProvider(auth);
              const vId = await phoneAuthProvider.verifyPhoneNumber(phoneInfoOptions, appVerifier!);

              setVerificationId(vId);
              setAuthStep('MFA_CHALLENGE');
              setLoading(false);

          } else {
              // LOGIN FLOW
              try {
                  const userCredential = await signInWithEmailAndPassword(auth, email, formData.password);
                  // Si pas de MFA requis, on logue directement
                  const dbUser = users.find(u => u.phone === formData.phone);
                  if (dbUser) onLogin(dbUser);
                  else throw new Error("Compte non synchronisé.");
              } catch (err: any) {
                  if (err.code === 'auth/multi-factor-auth-required') {
                      const resolver = getMultiFactorResolver(auth, err);
                      setMfaResolver(resolver);

                      const appVerifier = setupRecaptcha();
                      const phoneInfoOptions = {
                          multiFactorHint: resolver.hints[0],
                          session: resolver.session
                      };
                      const phoneAuthProvider = new PhoneAuthProvider(auth);
                      const vId = await phoneAuthProvider.verifyPhoneNumber(phoneInfoOptions, appVerifier!);

                      setVerificationId(vId);
                      setAuthStep('MFA_CHALLENGE');
                      setLoading(false);
                  } else {
                      throw err;
                  }
              }
          }
      } catch (err: any) {
          console.error(err);
          setError(err.message === "auth/invalid-credential" ? "Identifiants incorrects." : err.message);
          setLoading(false);
      }
  };

  const finalizeMfa = async (e: React.FormEvent) => {
      e.preventDefault();
      const code = verificationCode.join('');
      setLoading(true);

      try {
          const cred = PhoneAuthProvider.credential(verificationId, code);
          const multiFactorAssertion = PhoneMultiFactorGenerator.assertion(cred);

          if (viewMode === 'REGISTER') {
              // Finaliser l'enrôlement
              await multiFactor(auth.currentUser!).enroll(multiFactorAssertion, "Mobile Principal");

              // Upload images et création finale
              const avatarUrl = await uploadImage(avatarFile!, `avatars/${formData.phone}`);
              const newUser: User = {
                  id: auth.currentUser!.uid,
                  name: formData.name,
                  email: formData.email || `${formData.phone}@serviplus.ci`,
                  phone: formData.phone,
                  role: formData.role,
                  city: formData.city,
                  avatarUrl: avatarUrl,
                  verified: false,
                  createdAt: new Date().toISOString(),
                  idNumber: formData.idNumber
              };
              onRegister(newUser);
          } else {
              // Finaliser la connexion
              await mfaResolver.resolveSignIn(multiFactorAssertion);
              const dbUser = users.find(u => u.phone === formData.phone);
              if (dbUser) onLogin(dbUser);
          }
      } catch (err: any) {
          setError("Code invalide ou expiré.");
          setLoading(false);
      }
  };

  if (authStep === 'MFA_CHALLENGE') {
      return (
          <div className="min-h-screen flex items-center justify-center bg-gray-50 p-4 font-sans relative">
              <div className="absolute inset-0 bg-blue-900/60 backdrop-blur-sm"></div>
              <div className="bg-white p-8 rounded-3xl shadow-2xl w-full max-w-md relative z-10 animate-scale-in">
                  <div className="text-center mb-8">
                      <div className="bg-blue-100 w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4">
                          <Shield className="text-blue-600" size={32} />
                      </div>
                      <h2 className="text-2xl font-extrabold text-gray-900">Double Sécurité</h2>
                      <p className="text-gray-500 mt-2 text-sm">Identity Platform : Entrez le code SMS de vérification.</p>
                  </div>

                  {error && <div className="bg-red-50 text-red-600 p-3 rounded-xl mb-6 text-sm flex items-center"><AlertCircle size={16} className="mr-2" />{error}</div>}

                  <form onSubmit={finalizeMfa}>
                      <div className="flex justify-center space-x-2 mb-8">
                          {verificationCode.map((digit, index) => (
                              <input key={index} id={`code-${index}`} type="text" maxLength={1} value={digit} onChange={(e) => handleCodeChange(index, e.target.value)} className="w-10 h-12 text-center text-xl font-bold border-2 border-gray-300 rounded-xl focus:border-blue-500 outline-none" />
                          ))}
                      </div>
                      <button type="submit" disabled={loading} className="w-full bg-blue-600 text-white py-4 rounded-xl font-bold text-lg shadow-lg flex justify-center">
                          {loading ? <Loader2 className="animate-spin" /> : "Vérifier l'identité"}
                      </button>
                  </form>
                  <div id="recaptcha-container"></div>
              </div>
          </div>
      );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50 p-4 font-sans relative overflow-hidden">
        <div className="absolute inset-0 z-0">
             <img src={BACKGROUND_IMAGE} alt="Background" className="w-full h-full object-cover" />
             <div className="absolute inset-0 bg-blue-900/80 backdrop-blur-sm"></div>
        </div>

        <div className="bg-white rounded-3xl shadow-2xl w-full max-w-lg relative z-10 overflow-hidden animate-scale-in flex flex-col max-h-[90vh]">
            <div className="pt-8 pb-4 px-8 text-center">
                 <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-white font-bold text-2xl mx-auto mb-3 shadow-xl">S+</div>
                 <h1 className="text-2xl font-extrabold text-blue-900">Servi<span className="text-orange-500">+</span> <span className="text-[10px] bg-blue-100 text-blue-600 px-2 py-0.5 rounded-full ml-1 uppercase">Identity</span></h1>
                 <p className="text-gray-500 text-xs mt-1">Plateforme de mise en relation sécurisée</p>
            </div>

            <div className="px-8 pb-8 overflow-y-auto custom-scrollbar flex-1">
                <div className="flex bg-gray-100 p-1 rounded-xl mb-6">
                    <button onClick={() => setViewMode('LOGIN')} className={`flex-1 py-3 text-sm font-bold rounded-lg transition-all ${viewMode === 'LOGIN' ? 'bg-white text-blue-900 shadow-sm' : 'text-gray-500'}`}>Connexion</button>
                    <button onClick={() => setViewMode('REGISTER')} className={`flex-1 py-3 text-sm font-bold rounded-lg transition-all ${viewMode === 'REGISTER' ? 'bg-white text-blue-900 shadow-sm' : 'text-gray-500'}`}>Inscription</button>
                </div>

                {error && <div className="bg-red-50 border-l-4 border-red-500 text-red-700 p-3 rounded-r-lg mb-6 text-xs font-medium"><AlertCircle size={14} className="inline mr-2" />{error}</div>}

                <form onSubmit={handleAuthSubmit} className="space-y-4">
                    {viewMode === 'REGISTER' && (
                        <>
                            <div className="grid grid-cols-2 gap-3 mb-4">
                                <button type="button" onClick={() => setFormData({...formData, role: UserRole.CLIENT})} className={`p-3 rounded-xl border-2 text-xs font-bold transition-all ${formData.role === UserRole.CLIENT ? 'border-blue-500 bg-blue-50 text-blue-700' : 'border-gray-200'}`}>Client</button>
                                <button type="button" onClick={() => setFormData({...formData, role: UserRole.PROVIDER})} className={`p-3 rounded-xl border-2 text-xs font-bold transition-all ${formData.role === UserRole.PROVIDER ? 'border-orange-500 bg-orange-50 text-orange-700' : 'border-gray-200'}`}>Prestataire</button>
                            </div>
                            <div className="flex justify-center mb-4">
                                <div className="relative group cursor-pointer w-20 h-20">
                                    <div className={`w-full h-full rounded-full overflow-hidden border-4 ${avatarPreview ? 'border-blue-500' : 'border-gray-200'} bg-gray-100 flex items-center justify-center`}>
                                        {avatarPreview ? <img src={avatarPreview} alt="Avatar" className="w-full h-full object-cover" /> : <Camera size={24} className="text-gray-400" />}
                                    </div>
                                    <input type="file" accept="image/*" onChange={(e) => handleFileChange(e, 'AVATAR')} className="absolute inset-0 opacity-0 cursor-pointer z-10" />
                                </div>
                            </div>
                            <input type="text" name="name" placeholder="Nom Complet" value={formData.name} onChange={handleChange} className="w-full p-3 bg-gray-100 border rounded-xl text-sm font-bold" required />
                        </>
                    )}

                    <div className="relative">
                        <Phone className="absolute left-3 top-3.5 text-gray-400" size={16} />
                        <input type="tel" name="phone" placeholder="Numéro de téléphone" value={formData.phone} onChange={handleChange} className="w-full pl-10 p-3 bg-gray-100 border rounded-xl text-sm font-bold" required />
                    </div>

                    {viewMode === 'REGISTER' && (
                        <div className="grid grid-cols-2 gap-3">
                            <select name="city" value={formData.city} onChange={handleChange} className="p-3 bg-gray-100 border rounded-xl text-sm font-bold">{CITIES.map(c => <option key={c} value={c}>{c}</option>)}</select>
                            <input type="text" name="address" placeholder="Quartier" value={formData.address} onChange={handleChange} className="p-3 bg-gray-100 border rounded-xl text-sm font-bold" />
                        </div>
                    )}

                    <div className="relative">
                        <Lock className="absolute left-3 top-3.5 text-gray-400" size={16} />
                        <input type={showPassword ? "text" : "password"} name="password" placeholder="Mot de passe" value={formData.password} onChange={handleChange} className="w-full pl-10 pr-10 p-3 bg-gray-100 border rounded-xl text-sm font-bold" required />
                        <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute right-3 top-3.5 text-gray-400">{showPassword ? <EyeOff size={16} /> : <Eye size={16} />}</button>
                    </div>

                    {viewMode === 'REGISTER' && (
                         <div className="bg-gray-50 p-3 rounded-xl border border-gray-200">
                            <p className="text-[10px] font-bold text-gray-500 uppercase mb-2">Pièce d'identité (Requis)</p>
                            <input type="text" name="idNumber" placeholder="N° CNI / Passport" value={formData.idNumber} onChange={handleChange} className="w-full p-2 border rounded-lg text-xs font-bold mb-2" required />
                            <div className="grid grid-cols-2 gap-2">
                                <div className={`relative border-2 border-dashed rounded-lg p-2 flex flex-col items-center justify-center h-16 ${idCardRectoFile ? 'border-green-500 bg-green-50' : 'border-gray-300'}`}>
                                    <span className="text-[10px] font-bold">Recto</span>
                                    <input type="file" accept="image/*" onChange={(e) => handleFileChange(e, 'ID_RECTO')} className="absolute inset-0 opacity-0 cursor-pointer" />
                                </div>
                                <div className={`relative border-2 border-dashed rounded-lg p-2 flex flex-col items-center justify-center h-16 ${idCardVersoFile ? 'border-green-500 bg-green-50' : 'border-gray-300'}`}>
                                    <span className="text-[10px] font-bold">Verso</span>
                                    <input type="file" accept="image/*" onChange={(e) => handleFileChange(e, 'ID_VERSO')} className="absolute inset-0 opacity-0 cursor-pointer" />
                                </div>
                            </div>
                        </div>
                    )}

                    <button type="submit" disabled={loading} className="w-full bg-blue-600 text-white py-4 rounded-xl font-bold shadow-lg hover:bg-blue-700 transition-all flex justify-center">
                        {loading ? <Loader2 className="animate-spin" /> : (viewMode === 'LOGIN' ? "Connexion" : "Inscription")}
                    </button>
                    <div id="recaptcha-container"></div>
                </form>

                <div className="mt-6 text-center">
                    <button onClick={() => setViewMode(viewMode === 'LOGIN' ? 'REGISTER' : 'LOGIN')} className="text-blue-600 text-xs font-bold hover:underline">
                        {viewMode === 'LOGIN' ? "Créer un compte Servi+" : "Déjà membre ? Se connecter"}
                    </button>
                </div>
            </div>
        </div>
    </div>
  );
}

import { GoogleGenAI, Type } from "@google/genai";
import { AiEstimation } from "../types";

export const estimateMissionDetails = async (
  description: string,
  serviceType: string
): Promise<AiEstimation | null> => {
  // Fix: The API key must be obtained exclusively from the environment variable process.env.API_KEY.
  const apiKey = process.env.API_KEY || '';

  if (!apiKey) return null;

  // Fix: Initialize the GoogleGenAI client with the mandatory apiKey parameter.
  const ai = new GoogleGenAI({ apiKey });

  try {
    // Fix: Use 'gemini-3-flash-preview' for basic text tasks.
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Estimate duration and price for ${serviceType}: ${description}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            estimatedDuration: { type: Type.NUMBER },
            suggestedPrice: { type: Type.NUMBER },
            descriptionImprovement: { type: Type.STRING },
          },
          required: ["estimatedDuration", "suggestedPrice", "descriptionImprovement"],
        },
      },
    });
    // Fix: Access response.text as a property.
    const text = response.text;
    if (!text) return null;
    return JSON.parse(text) as AiEstimation;
  } catch (error) {
    console.error("Gemini Estimation Error:", error);
    return null;
  }
};

